function selectedTeamProjectAccessContext() {
  const flow = normalizeProjectFlow(state.projectFlow?.data || {});
  const routeProjectId = routeWorkspaceProjectId();
  const projectId = routeProjectId || String(flow.project_id || "").trim().toLowerCase();
  if (
    !isWorkspaceProjectId(projectId)
    || flow.project_id !== projectId
    || (routeProjectId && routeProjectId !== projectId)
  ) return null;
  const project = [flow.project, ...flow.projects]
    .filter(Boolean)
    .find((item) => String(item?.id || "").trim().toLowerCase() === projectId);
  if (!project) return null;
  return {
    id: projectId,
    name: String(project.name || "Проект").trim() || "Проект",
  };
}

function normalizeProjectAccessRoster(raw, expectedProjectId) {
  const source = raw?.data && typeof raw.data === "object" ? raw.data : raw;
  const projectId = String(source?.project_id || "").trim().toLowerCase();
  if (
    !source
    || source.ok !== true
    || projectId !== expectedProjectId
    || !Array.isArray(source.members)
    || source.capabilities?.manage_members !== true
  ) {
    throw new CreatorApiError(
      "Сервис доступа вернул неполный список. Обновите проект и повторите проверку.",
      { code: "project_members_response_invalid" },
    );
  }
  const members = source.members.map((member) => ({
    profileId: String(member?.profile_id || "").trim().toLowerCase(),
    displayName: String(member?.display_name || "").trim(),
    email: String(member?.email || "").trim(),
    organizationRole: String(member?.organization_role || "").trim().toLowerCase(),
    accessRole: String(member?.access_role || "member").trim().toLowerCase(),
    status: String(member?.status || "").trim().toLowerCase(),
    updatedAt: String(member?.updated_at || ""),
  }));
  if (members.some((member) => !isWorkspaceProjectId(member.profileId))) {
    throw new CreatorApiError(
      "Сервис доступа вернул неполный список. Обновите проект и повторите проверку.",
      { code: "project_members_response_invalid" },
    );
  }
  return { projectId, members };
}

function teamProjectAccessCandidates(members) {
  const candidates = new Map();
  (Array.isArray(members) ? members : []).forEach((member) => {
    const profileId = String(member?.profile_id || member?.user_id || "")
      .trim()
      .toLowerCase();
    if (!isWorkspaceProjectId(profileId) || candidates.has(profileId)) return;
    candidates.set(profileId, {
      profileId,
      displayName: String(member?.display_name || "").trim(),
      email: String(member?.email || "").trim(),
      role: String(member?.role || "").trim().toLowerCase(),
      status: String(member?.status || "active").trim().toLowerCase(),
      teamCandidate: true,
    });
  });
  return [...candidates.values()];
}

async function loadProjectMembers({ force = false, silent = false } = {}) {
  if (!canManageTeam() || !state.api?.projectMembers) return null;
  const context = selectedTeamProjectAccessContext();
  if (!context) return null;
  const target = state.projectAccess;
  if (
    !force
    && ["loading", "refreshing"].includes(target.status)
    && target.projectId === context.id
  ) return null;
  if (
    !force
    && target.status === "ready"
    && target.projectId === context.id
  ) return target.data;

  const requestEpoch = state.dataEpoch;
  const requestUserId = state.user?.id;
  const requestId = target.requestId + 1;
  const projectChanged = target.projectId !== context.id;
  target.requestId = requestId;
  target.projectId = context.id;
  if (projectChanged) {
    target.data = null;
    target.notice = "";
  }
  target.status = target.data ? "refreshing" : "loading";
  target.error = "";
  if (!silent && state.route.path === "/workspace/team") renderWorkspace("team");

  const requestIsCurrent = () => (
    requestEpoch === state.dataEpoch
    && requestUserId === state.user?.id
    && requestId === target.requestId
    && target.projectId === context.id
    && selectedTeamProjectAccessContext()?.id === context.id
  );
  try {
    const raw = await withUiTimeout(
      state.api.projectMembers({ projectId: context.id }),
      WORKSPACE_REQUEST_TIMEOUT_MS,
      "project_members_timeout",
    );
    if (!requestIsCurrent()) return null;
    target.data = normalizeProjectAccessRoster(raw, context.id);
    target.status = "ready";
    return target.data;
  } catch (error) {
    if (!requestIsCurrent()) return null;
    target.status = "error";
    target.error = actionErrorMessage(error);
    return null;
  } finally {
    if (requestIsCurrent() && state.route.path === "/workspace/team") {
      renderWorkspace("team");
    }
  }
}

function projectAccessMemberRows(teamMembers, rosterMembers) {
  const rosterByProfile = new Map(
    rosterMembers.map((member) => [member.profileId, member]),
  );
  const candidates = teamProjectAccessCandidates(teamMembers);
  const candidateIds = new Set(candidates.map((member) => member.profileId));
  rosterMembers.forEach((member) => {
    if (candidateIds.has(member.profileId)) return;
    candidates.push({
      profileId: member.profileId,
      displayName: member.displayName,
      email: member.email,
      role: member.organizationRole,
      status: "active",
      teamCandidate: false,
    });
  });
  return candidates
    .map((candidate) => ({
      ...candidate,
      access: rosterByProfile.get(candidate.profileId) || null,
    }))
    .sort((left, right) => {
      const activeDelta = Number(right.access?.status === "active")
        - Number(left.access?.status === "active");
      if (activeDelta) return activeDelta;
      return String(left.displayName || left.email || left.profileId)
        .localeCompare(String(right.displayName || right.email || right.profileId), "ru");
    });
}

function projectAccessMemberTable(teamMembers, rosterMembers, projectId) {
  const rows = projectAccessMemberRows(teamMembers, rosterMembers);
  if (!rows.length) {
    return emptyState(
      "◎",
      "Нет участников для проекта",
      "Сначала пригласите человека в команду. Доступ ко всем проектам автоматически не выдаётся.",
      { href: "#/workspace/team?view=invite", label: "Пригласить участника" },
    );
  }
  return `<div class="table-wrap"><table class="data-table project-access-table">
    <thead><tr><th>Участник команды</th><th>Рабочая роль</th><th>Доступ к проекту</th><th>Действие</th></tr></thead>
    <tbody>${rows.map((member) => {
      const hasAccess = member.access?.status === "active";
      const organizationActive = member.status === "active";
      const operational = PROJECT_ACCESS_OPERATIONAL_ROLES.has(member.role);
      const protectedRole = ["owner", "admin"].includes(member.role);
      const busy = state.projectAccess.busyProfileId === member.profileId;
      let actionMarkup = `<span class="tiny muted">Сначала нужна активная рабочая роль</span>`;
      if (!member.teamCandidate) {
        actionMarkup = `<span class="tiny muted">Обновите список команды для изменения</span>`;
      } else if (organizationActive && operational && protectedRole && hasAccess) {
        actionMarkup = `<span class="tiny muted">Обязательный доступ защищён</span>`;
      } else if (organizationActive && operational) {
        actionMarkup = `<button class="btn ${hasAccess ? "btn-secondary" : ""} btn-small" type="button" data-action="${hasAccess ? "revoke-project-member" : "grant-project-member"}" data-project-id="${escapeHtml(projectId)}" data-profile-id="${escapeHtml(member.profileId)}" ${busy ? "disabled" : ""}>${busy ? "Сохраняем…" : hasAccess ? "Отозвать" : protectedRole ? "Восстановить доступ" : "Выдать доступ"}</button>`;
      }
      return `<tr data-project-member-profile-id="${escapeHtml(member.profileId)}">
        <td><strong>${escapeHtml(member.displayName || member.email || "Участник")}</strong>${member.displayName && member.email ? `<br /><small class="muted">${escapeHtml(member.email)}</small>` : ""}</td>
        <td>${escapeHtml(humanRole(member.role || "trainee"))}${organizationActive ? "" : `<br />${statusBadge(member.status || "inactive")}`}</td>
        <td>${hasAccess ? `<span class="badge badge-success">Есть доступ</span>` : `<span class="badge">Нет доступа</span>`}</td>
        <td>${actionMarkup}</td>
      </tr>`;
    }).join("")}</tbody>
  </table></div>`;
}

function projectAccessMarkup(teamMembers) {
  const flow = normalizeProjectFlow(state.projectFlow?.data || {});
  const projects = flow.projects.filter((project) =>
    isWorkspaceProjectId(String(project?.id || "").trim().toLowerCase()),
  );
  const context = selectedTeamProjectAccessContext();
  const selectedId = context?.id || routeWorkspaceProjectId();
  const selector = projects.length
    ? `<label class="field"><span>Проект *</span><select data-project-access-project aria-label="Проект для управления доступом">${context ? "" : `<option value="">Выберите проект</option>`}${projects.map((project) => {
      const projectId = String(project.id).trim().toLowerCase();
      return `<option value="${escapeHtml(projectId)}" ${projectId === selectedId ? "selected" : ""}>${escapeHtml(project.name || "Проект")}</option>`;
    }).join("")}</select><small class="field-hint">Выбор сохранится в URL; сервер заново подтвердит точный проект перед изменением доступа.</small></label>`
    : "";

  let body;
  if (["idle", "loading", "refreshing"].includes(state.projectFlow.status) && !projects.length) {
    body = `<div class="loading-line" aria-hidden="true"><span></span></div><p class="muted">Загружаем доступные проекты…</p>`;
  } else if (state.projectFlow.status === "error" && !projects.length) {
    body = `${alertMarkup("Не удалось загрузить серверный список проектов.", "warning")}<button class="btn btn-secondary btn-small" type="button" data-action="retry-project-flow">Повторить</button>`;
  } else if (!projects.length) {
    body = emptyState("◇", "Нет доступных проектов", "Создайте проект на рабочем столе, затем вернитесь к управлению доступом.", { href: "#/workspace/home", label: "Открыть проекты" });
  } else if (!context) {
    body = `${selector}${alertMarkup(routeWorkspaceProjectId()
      ? "Сервер ещё подтверждает выбранный в URL проект. Изменения доступа пока остановлены."
      : "Выберите один проект. Приглашение в команду само по себе не открывает остальные проекты.", "info")}`;
  } else {
    const target = state.projectAccess;
    const exactState = target.projectId === context.id;
    if (!exactState || target.status === "idle") {
      window.queueMicrotask(() => { void loadProjectMembers({ silent: true }); });
    }
    let rosterBody = `<div class="loading-line" aria-hidden="true"><span></span></div><p class="muted">Проверяем участников проекта на сервере…</p>`;
    if (exactState && target.status === "error") {
      rosterBody = `${alertMarkup(target.error || "Не удалось обновить доступ к проекту.", "warning")}<button class="btn btn-secondary btn-small" type="button" data-action="refresh-project-members">Повторить</button>`;
    } else if (exactState && target.data) {
      rosterBody = `${target.notice ? alertMarkup(target.notice, "success") : ""}${target.error ? alertMarkup(target.error, "warning") : ""}${target.status === "refreshing" ? `<p class="tiny muted" role="status">Обновляем серверный список…</p>` : ""}${projectAccessMemberTable(teamMembers, target.data.members, context.id)}`;
    }
    body = `${selector}<div class="card-header" style="padding-left:0; padding-right:0"><div><p class="eyebrow">Выбранный проект</p><h3>${escapeHtml(context.name)}</h3></div><button class="btn btn-secondary btn-small" type="button" data-action="refresh-project-members" ${["loading", "refreshing"].includes(target.status) ? "disabled" : ""}>Обновить доступ</button></div>${rosterBody}`;
  }

  return `<section class="card card-pad project-access-panel" data-project-access-project-id="${escapeHtml(context?.id || "")}" style="margin-top:22px">
    <p class="eyebrow">Проекты · общий результат</p>
    <h2 style="font:600 1.55rem/1.15 Georgia,serif; margin:0 0 8px">Кто видит файлы выбранного проекта</h2>
    <p class="muted">Доступ выдаётся явно только к одному проекту. Новый участник команды не получает другие проекты автоматически; владелец, администратор и создатель проекта защищены сервером от отзыва.</p>
    ${body}
  </section>`;
}

async function changeProjectMemberAccess(control, accessAction) {
  const projectId = String(control?.dataset?.projectId || "").trim().toLowerCase();
  const profileId = String(control?.dataset?.profileId || "").trim().toLowerCase();
  const context = selectedTeamProjectAccessContext();
  const routeProjectId = routeWorkspaceProjectId();
  if (
    !canManageTeam()
    || !context
    || !isWorkspaceProjectId(profileId)
    || !routeProjectId
    || routeProjectId !== projectId
    || context.id !== projectId
  ) {
    toast("Проект или участник изменились. Обновите серверный список доступа.", "error");
    resetProjectAccessState();
    if (state.route.path === "/workspace/team") renderWorkspace("team");
    return;
  }

  const candidate = teamProjectAccessCandidates(
    listFrom(state.sections.team.data || {}, "members"),
  ).find((member) => member.profileId === profileId);
  if (
    !candidate
    || candidate.status !== "active"
    || !PROJECT_ACCESS_OPERATIONAL_ROLES.has(candidate.role)
  ) {
    toast("Доступ можно изменить только для активного участника с рабочей ролью.", "error");
    return;
  }

  const target = state.projectAccess;
  const currentMember = target.projectId === projectId
    ? target.data?.members?.find((member) => member.profileId === profileId)
    : null;
  const hasAccess = currentMember?.status === "active";
  if (
    (accessAction === "grant" && hasAccess)
    || (accessAction === "revoke" && !hasAccess)
  ) {
    toast("Состояние доступа уже изменилось. Обновляем список без повторной команды.", "info");
    await loadProjectMembers({ force: true });
    return;
  }
  if (accessAction === "revoke" && ["owner", "admin"].includes(candidate.role)) {
    toast("Обязательный доступ владельца или администратора защищён.", "info");
    return;
  }

  const requestEpoch = state.dataEpoch;
  const requestUserId = state.user?.id;
  target.busyProfileId = profileId;
  target.error = "";
  target.notice = "";
  if (state.route.path === "/workspace/team") renderWorkspace("team");
  try {
    const raw = accessAction === "grant"
      ? await state.api.grantProjectMember(profileId, { projectId })
      : await state.api.revokeProjectMember(profileId, { projectId });
    if (
      requestEpoch !== state.dataEpoch
      || requestUserId !== state.user?.id
      || selectedTeamProjectAccessContext()?.id !== projectId
      || routeWorkspaceProjectId() !== projectId
    ) return;
    const source = raw?.data && typeof raw.data === "object" ? raw.data : raw;
    const expectedStatus = accessAction === "grant" ? "active" : "revoked";
    if (
      source?.ok !== true
      || String(source.project_id || "").trim().toLowerCase() !== projectId
      || String(source.profile_id || "").trim().toLowerCase() !== profileId
      || String(source.status || "").trim().toLowerCase() !== expectedStatus
    ) {
      throw new CreatorApiError(
        "Сервер не подтвердил изменение доступа. Обновите список перед повтором.",
        { code: "project_member_mutation_response_invalid" },
      );
    }
    target.notice = accessAction === "grant"
      ? `Участнику ${candidate.displayName || candidate.email || "команды"} открыт только выбранный проект.`
      : `Доступ участника ${candidate.displayName || candidate.email || "команды"} к выбранному проекту отозван.`;
    await loadProjectMembers({ force: true, silent: true });
  } catch (error) {
    if (
      requestEpoch === state.dataEpoch
      && requestUserId === state.user?.id
      && selectedTeamProjectAccessContext()?.id === projectId
    ) {
      target.error = actionErrorMessage(error);
      target.status = target.data ? "ready" : "error";
    }
  } finally {
    if (
      requestEpoch === state.dataEpoch
      && requestUserId === state.user?.id
      && target.busyProfileId === profileId
    ) target.busyProfileId = "";
    if (state.route.path === "/workspace/team") renderWorkspace("team");
  }
}

function renderTeamSection(sectionState) {
  if (!canManageTeam()) {
    return `<div class="page-wrap">${alertMarkup("Управление командой доступно только руководителю.", "danger")}</div>`;
  }
  const requestedView = String(state.route.query.get("view") || "members");
  const teamView = ["invite", "access", "members", "reviews", "review", "budget", "campaigns", "campaign", "new-campaign", "health", "accounts"].includes(requestedView)
    ? requestedView
    : "members";
  if (teamView === "health" && state.managerDashboard.status === "idle") {
    window.queueMicrotask(() => loadManagerDashboard({ silent: true }));
  }
  if (teamView === "accounts" && state.teamAccounts.status === "idle") {
    window.queueMicrotask(() => loadTeamAccounts({ silent: true }));
  }
  if (["budget", "campaigns", "campaign", "new-campaign"].includes(teamView) && state.generationSpend.status === "idle") {
    window.queueMicrotask(() => loadGenerationSpendOverview({ silent: true }));
  }
  const requestedCampaignId = safeWorkspaceRouteEntityId("campaign");
  const requestedPracticalReviewId = safeWorkspaceRouteEntityId("review");
  const members = listFrom(sectionState.data || {}, "members");
  const teamGroup = ["invite", "access", "members"].includes(teamView)
    ? "people"
    : ["reviews", "review"].includes(teamView)
      ? "reviews"
      : ["budget", "campaigns", "campaign", "new-campaign"].includes(teamView)
        ? "spend"
        : teamView === "accounts"
          ? "accounts"
          : "health";
  const teamContextActions = teamGroup === "people"
    ? [
        { view: "members", href: "#/workspace/team?view=members", label: "Участники" },
        { view: "invite", href: "#/workspace/team?view=invite", label: "Пригласить" },
        { view: "access", href: "#/workspace/team?view=access", label: "Изменить доступ" },
      ]
    : teamGroup === "spend"
      ? [
          { view: "campaigns", href: "#/workspace/team?view=campaigns", label: "Кампании" },
          { view: "budget", href: "#/workspace/team?view=budget", label: "Общий бюджет" },
          { view: "new-campaign", href: "#/workspace/team?view=new-campaign", label: "Новая кампания" },
          ...(teamView === "campaign" && requestedCampaignId
            ? [{ view: "campaign", href: `#/workspace/team?view=campaign&campaign=${encodeURIComponent(requestedCampaignId)}`, label: "Текущая кампания" }]
            : []),
        ]
      : [];
  const invitePanel = `
    <div class="split-grid team-invite-panel" style="margin-top:18px">
      <section class="card card-pad">
        <p class="eyebrow">Массовое приглашение</p>
        <h2 style="font:600 1.55rem/1.15 Georgia,serif; margin:0 0 8px">Один email на строку</h2>
        <p class="muted tiny">Повторы будут удалены до отправки. Максимум 50 уникальных адресов за один запуск.</p>
        <form id="team-invite-form" class="form-stack" novalidate>
          <label class="field">
            <span>Рабочие адреса *</span>
            <textarea name="emails" required rows="12" maxlength="16000" spellcheck="false" autocomplete="off" placeholder="creator-01@company.ru&#10;creator-02@company.ru"></textarea>
          </label>
          <button class="btn btn-block" type="submit" data-primary-action="true">Отправить приглашения</button>
        </form>
      </section>
      <section class="card">
        <div class="card-header"><div><p class="eyebrow">Последний запуск</p><h2>Результаты почтовых запросов</h2></div></div>
        ${state.teamInviteResult ? teamInviteResultMarkup(state.teamInviteResult) : emptyState("◎", "Приглашений ещё не было", "После запуска здесь появится принятый сервисом статус по каждому адресу.")}
      </section>
    </div>
  `;
  const membersPanel = `
    <section class="card team-members-panel">
      <div class="card-header"><div><p class="eyebrow">Доступ и результат</p><h2>Участники команды</h2></div><button class="btn btn-secondary btn-small" type="button" data-action="refresh-section" data-section="team">Обновить</button></div>
      ${sectionBody(sectionState, members.length ? teamMembersTable(members) : emptyState("◎", "В команде пока никого нет", "Отправьте приглашения — новые участники появятся после первого входа.", { href: "#/workspace/team?view=invite", label: "Пригласить участников" }))}
    </section>
  `;
  const activePanel = teamView === "invite"
    ? invitePanel
    : teamView === "access"
      ? `<section class="team-access-panel">${accessCenterMarkup(state.accessCenter)}</section>`
      : teamView === "reviews"
        ? `<section class="team-reviews-panel">${trainingPracticalReviewQueueMarkup(
          state.bootstrap?.training?.practicalReviews || [],
          { interactive: false },
        )}</section>`
        : teamView === "review"
          ? `<section class="team-reviews-panel">${requestedPracticalReviewId
            ? trainingPracticalReviewQueueMarkup(
              state.bootstrap?.training?.practicalReviews || [],
              { interactive: true, reviewId: requestedPracticalReviewId },
            )
            : emptyState("?", "Не указана пробная работа", "Откройте очередь и выберите одну запись для решения.", { href: "#/workspace/team?view=reviews", label: "Открыть очередь" })}</section>`
          : teamView === "accounts"
            ? `<section class="team-accounts-panel">${teamAccountsPanelMarkup()}</section>`
            : teamView === "health"
            ? `<section class="team-health-panel">${managerDashboardSectionMarkup()}</section>`
            : ["budget", "campaigns", "campaign", "new-campaign"].includes(teamView)
              ? `<section class="team-spend-panel">${managerGenerationSpendMarkup(state.generationSpend, {
                canEdit: canManageGenerationSpendPolicy(),
                view: teamView === "budget" ? "policy" : teamView,
                campaignId: requestedCampaignId,
              })}</section>`
              : `${membersPanel}${projectAccessMarkup(members)}`;
  return `
    <div class="page-wrap" data-team-view="${teamView}">
      ${pageHeader("Команда", "Здесь остаются обучение, проверки и операционные показатели. Состав и рабочие аккаунты управляются в отдельной админке.", `<a class="btn btn-secondary btn-small" href="#${ADMIN_PEOPLE_PATH}">Открыть админку</a><span class="badge badge-info">До 50 человек</span>`)}
      ${alertMarkup("Каждый новый участник входит как trainee. Рабочие разделы откроются только после четырёх курсов, принятой руководителем пробной работы и успешного экзамена из 12 сценариев.", "info")}
      ${workspaceActionSwitch("team-action-switch team-action-switch--groups", "Область управления командой", teamGroup, [
        { view: "people", href: "#/workspace/team?view=members", label: "Люди" },
        { view: "accounts", href: "#/workspace/team?view=accounts", label: "Аккаунты" },
        { view: "reviews", href: "#/workspace/team?view=reviews", label: "Проверки" },
        { view: "spend", href: "#/workspace/team?view=campaigns", label: "Расходы" },
        { view: "health", href: "#/workspace/team?view=health", label: "Состояние" },
      ])}
      ${teamContextActions.length ? workspaceActionSwitch(
        "team-action-switch team-action-switch--context",
        "Текущее действие в выбранной области",
        teamView,
        teamContextActions,
      ) : ""}
      ${activePanel}
    </div>
  `;
}

function managerDashboardSectionMarkup() {
  const dashboard = state.managerDashboard;
  if (["idle", "loading"].includes(dashboard.status) && !dashboard.data) {
    return `<section class="manager-funnel manager-dashboard-loading" role="status"><div class="loading-line" aria-hidden="true"><span></span></div><strong>Собираем, где команда остановилась…</strong><p class="muted">Письмо, вход, обучение, генерация, публикация и выплата проверяются одним отчётом.</p></section>`;
  }
  if (dashboard.status === "error" && !dashboard.data) {
    return `<section class="manager-funnel">${alertMarkup("Не удалось загрузить очередь внимания. Список участников выше продолжает работать.", "warning")}<button class="btn btn-secondary btn-small" type="button" data-action="refresh-manager-dashboard">Повторить загрузку</button>${managerOperationalHealthMarkup(state.operationalHealth)}</section>`;
  }
  return `${dashboard.status === "refreshing" ? `<p class="tiny muted manager-refresh-note" role="status">Обновляем сводку без остановки страницы…</p>` : ""}${dashboard.status === "error" ? alertMarkup("Не удалось обновить сводку. Ниже показаны последние сохранённые данные — нажмите «Обновить» ещё раз позже.", "warning") : ""}${managerDashboardMarkup(dashboard.data || {}, state.operationalHealth)}`;
}

function teamMemberHypothesesMarkup(member) {
  const hypotheses = Array.isArray(state.sections.team.data?._hypotheses)
    ? state.sections.team.data._hypotheses
    : [];
  const memberId = String(member.user_id || member.id || "").toLowerCase();
  const projectId = currentWorkspaceProjectId();
  const own = hypotheses.filter(
    (entry) => String(entry.owner_profile_id || "").toLowerCase() === memberId,
  );
  const links = own.map((entry) => `<a class="tiny" href="#/workspace/hypotheses?project_id=${encodeURIComponent(projectId)}&hypothesis=${encodeURIComponent(String(entry.id))}" title="${escapeHtml(String(entry.title || ""))}">${escapeHtml(String(entry.code || ""))}</a>`).join(", ");
  // Выдача прямо из таблицы людей (фидбек владельца 27.08: «где гипотезу
  // выдать») — тот же RPC, что и селект «Ответственный» в срезе гипотезы;
  // право закрепления проверяет сервер (owner/admin/producer).
  const assignable = hypotheses.filter(
    (entry) => String(entry.owner_profile_id || "").toLowerCase() !== memberId,
  );
  const assignSelect = assignable.length && memberId
    ? `<select class="tiny" data-team-hypothesis-assign data-profile-id="${escapeHtml(memberId)}" title="Гипотеза закрепится за этим сотрудником и сама подставится ему в формах генерации">
        <option value="">${own.length ? "+ Выдать ещё…" : "+ Выдать гипотезу…"}</option>
        ${assignable.map((entry) => `<option value="${escapeHtml(String(entry.id))}">${escapeHtml(String(entry.code || ""))} · ${escapeHtml(String(entry.title || "").slice(0, 48))}</option>`).join("")}
      </select>`
    : "";
  if (!links && !assignSelect) return `<span class="muted">—</span>`;
  return `${links}${links && assignSelect ? "<br />" : ""}${assignSelect}`;
}

async function assignHypothesisFromTeam(select) {
  const hypothesisId = String(select.value || "");
  const profileId = String(select.dataset.profileId || "");
  if (!hypothesisId || !profileId) return;
  select.disabled = true;
  try {
    await state.api.call("creator_assign_content_hypothesis_owner", {
      organization_id: String(state.api.organizationId || ""),
      hypothesis_id: hypothesisId,
      owner_profile_id: profileId,
    });
    toast("Гипотеза закреплена: в формах генерации она подставится сотруднику сама.", "success");
    state.sections.hypotheses.status = "idle";
    state.sections.hypotheses.data = null;
    state.sections.team.status = "idle";
    state.sections.team.data = null;
    await loadSection("team");
  } catch (error) {
    select.disabled = false;
    select.value = "";
    toast(actionErrorMessage(error), "error");
  }
}

function teamMembersTable(members) {
  const hypotheses = Array.isArray(state.sections.team.data?._hypotheses)
    ? state.sections.team.data._hypotheses
    : [];
  // Пустая колонка обязана объяснять себя: без единой гипотезы в проекте
  // выдавать нечего, и «—» без подсказки читается как поломка (27.08).
  const hypothesesHint = hypotheses.length
    ? ""
    : `<p class="muted tiny" style="margin:8px 0 0">В колонке «Гипотезы» пусто, потому что в проекте ещё нет ни одной гипотезы. <a href="#/workspace/hypotheses?project_id=${encodeURIComponent(currentWorkspaceProjectId())}">Создайте первую в папке «Гипотезы»</a> — здесь появится «+ Выдать гипотезу…».</p>`;
  return `<div class="table-wrap"><table class="data-table">
    <thead><tr><th>Участник</th><th>Роль</th><th>Курсы</th><th>Экзамен</th><th>Задачи</th><th>Публикации</th><th>Гипотезы</th></tr></thead>
    <tbody>${members.map((member) => `<tr data-member-id="${escapeHtml(member.user_id || member.id || member.email || "")}">
      <td><strong>${escapeHtml(member.display_name || member.email || "Участник")}</strong>${member.display_name && member.email ? `<br /><small class="muted">${escapeHtml(member.email)}</small>` : ""}${member.status && member.status !== "active" ? `<br />${statusBadge(member.status)}` : ""}</td>
      <td>${escapeHtml(humanRole(member.role || "trainee"))}</td>
      <td><strong>${formatNumber(member.courses_completed ?? 0)}/${formatNumber(member.courses_required ?? 4)}</strong></td>
      <td>${normalizeBoolean(member.exam_passed) ? statusBadge("passed") : statusBadge("pending")}</td>
      <td>${formatNumber(member.tasks_done ?? 0)}/${formatNumber(member.tasks_total ?? 0)}</td>
      <td>${formatNumber(member.published_count ?? 0)}</td>
      <td>${teamMemberHypothesesMarkup(member)}</td>
    </tr>`).join("")}</tbody>
  </table></div>${hypothesesHint}`;
}

function teamInviteResultMarkup(result) {
  const rows = Array.isArray(result?.results) ? result.results : [];
  const smtpRequired = result?.smtp_required === true || rows.some((item) => item.status === "smtp_required");
  const statusLabels = {
    invited: "Запрос принят сервисом; доставка письма не подтверждена",
    already_exists: "Существующий аккаунт подключён; новое письмо не отправлялось",
    rate_limited: "Лимит отправки",
    smtp_required: "Почта не настроена",
    failed: "Не отправлено",
    pending_verification: "Ответ не получен вовремя — проверьте историю перед повтором",
  };
  const reasonLabels = {
    invite_request_accepted: "Приглашение принято почтовым сервисом",
    existing_account_connected: "Доступ существующего аккаунта активирован",
    auth_user_already_exists: "Аккаунт уже существует",
    email_rate_limited: "Сработал лимит почтовых запросов",
    smtp_not_configured: "SMTP-провайдер не разрешил отправку",
    auth_invite_failed: "Auth не принял запрос приглашения",
    password_marker_failed: "Не удалось включить обязательную смену пароля",
    membership_provision_failed: "Не удалось подготовить членство в команде",
    membership_reconcile_failed: "Не удалось подключить существующий аккаунт",
    auth_user_missing: "Auth не вернул созданный аккаунт",
    client_timeout: "Портал перестал ждать ответ, операция могла завершиться позже",
  };
  const retryable = rows.filter((item) => !["invited", "already_exists"].includes(item.status));
  return `
    <div class="card-pad" style="padding-top:0">
      ${result.requested_at ? `<p class="tiny muted">Последний запрос: ${escapeHtml(formatDate(result.requested_at, true))}${result.request_id ? ` · № ${escapeHtml(String(result.request_id).slice(0, 8))}` : ""}</p>` : ""}
      <div class="metrics-grid metrics-grid-three" style="margin-bottom:16px">
        <article class="metric-card"><span class="metric-label">Запрошено</span><strong>${formatNumber(result.requested ?? rows.length)}</strong></article>
        <article class="metric-card"><span class="metric-label">Принято сервисом</span><strong>${formatNumber(result.invited ?? 0)}</strong></article>
        <article class="metric-card"><span class="metric-label">Уже существуют</span><strong>${formatNumber(result.already_exists ?? 0)}</strong></article>
      </div>
      ${Number(result.invited || 0) > 0 ? alertMarkup("Статус «Принято сервисом» подтверждает запрос, но не попадание письма во «Входящие». Участнику нужно проверить также «Спам» и использовать только самое свежее письмо.", "info") : ""}
      ${smtpRequired ? alertMarkup("Почтовая отправка портала ещё не настроена. Адреса со статусом «Почта не настроена» не получили приглашение.", "warning") : ""}
      ${rows.some((item) => item.status === "rate_limited") ? alertMarkup("Достигнут лимит отправки писем. Не повторяйте весь список: позже отправьте только адреса со статусом «Лимит отправки».", "warning") : ""}
      ${result.persistence === "unavailable" ? alertMarkup("Сервер не подтвердил сохранение истории этого запуска. Не повторяйте список вслепую: сначала нажмите «Обновить».", "warning") : ""}
      <div class="table-wrap"><table class="data-table">
        <thead><tr><th>Email</th><th>Результат</th></tr></thead>
        <tbody>${rows.map((item) => `<tr><td>${escapeHtml(item.email || "—")}</td><td>${statusBadge(item.status || "failed")}<br /><small class="muted">${escapeHtml(statusLabels[item.status] || "Неизвестный результат")}</small>${item.reason_code ? `<br /><small class="muted">${escapeHtml(reasonLabels[item.reason_code] || item.reason_code)}</small>` : ""}</td></tr>`).join("")}</tbody>
      </table></div>
      ${retryable.length ? `<button class="btn btn-secondary btn-small" type="button" data-action="prepare-failed-invites" style="margin-top:14px">Заполнить только неудачные (${retryable.length})</button>` : ""}
    </div>
  `;
}

function teamInviteStorageKey() {
  const userId = state.user?.id;
  const organizationId = state.bootstrap?.organization?.id;
  return userId && organizationId
    ? `contentengine.invite-result.v1.${organizationId}.${userId}`
    : null;
}

function persistTeamInviteResult(result) {
  const key = teamInviteStorageKey();
  if (!key || !result) return;
  try {
    window.sessionStorage.setItem(key, JSON.stringify({
      expiresAt: Date.now() + 24 * 60 * 60 * 1000,
      result,
    }));
  } catch {
    // The server-side invite ledger remains the source of truth.
  }
}

function restoreTeamInviteResult() {
  const key = teamInviteStorageKey();
  if (!key) return null;
  try {
    const saved = JSON.parse(window.sessionStorage.getItem(key) || "null");
    if (!saved?.result || Number(saved.expiresAt || 0) < Date.now()) {
      window.sessionStorage.removeItem(key);
      return null;
    }
    return saved.result;
  } catch {
    window.sessionStorage.removeItem(key);
    return null;
  }
}

function feedbackCard(item) {
  return `<article class="card feedback-card"><div class="feedback-top"><div><p class="eyebrow">${escapeHtml(item.category || "запрос")} · ${formatDate(item.created_at)}</p><h3>${escapeHtml(item.title || "Без заголовка")}</h3><p>${escapeHtml(item.details || item.description || "")}</p></div>${statusBadge(item.status || "new")}</div>${item.response ? alertMarkup(item.response, "success") : ""}</article>`;
}

function workspaceDirectionMarkup(meta) {
  if (!meta?.now || !meta?.done || !meta?.nextHref) return "";
  return `
    <section class="workspace-direction card" aria-label="Что делать в этом разделе">
      <div class="workspace-direction-heading">
        <span class="direction-seal" aria-hidden="true">A</span>
        <div><p class="eyebrow">Маршрут без догадок</p><h2>Сделайте один шаг и проверьте результат</h2></div>
      </div>
      <ol class="workspace-direction-steps">
        <li><span>01</span><div><small>Сделайте сейчас</small><strong>${escapeHtml(meta.now)}</strong></div></li>
        <li><span>02</span><div><small>Готово, когда</small><strong>${escapeHtml(meta.done)}</strong></div></li>
        <li><span>03</span><div><small>После этого</small><strong>${escapeHtml(meta.nextLabel)}</strong></div></li>
      </ol>
      <div class="workspace-direction-footer">
        <p><span aria-hidden="true">!</span><strong>Стоп-правило:</strong> ${escapeHtml(meta.guard)}</p>
        <a class="direction-next-link" href="${escapeHtml(meta.nextHref)}">Когда закончите: ${escapeHtml(meta.nextLabel)} <span aria-hidden="true">→</span></a>
      </div>
    </section>
  `;
}

function workspaceActionGuideMarkup(meta) {
  if (!meta?.now || !meta?.done || !meta?.nextHref) return "";
  return `
    <section class="workspace-action-guide" aria-label="Текущее действие и следующий шаг">
      <span class="workspace-action-guide__step" aria-hidden="true">→</span>
      <div class="workspace-action-guide__now">
        <small>Сейчас</small>
        <strong>${escapeHtml(meta.now)}</strong>
        <span><b>Готово, когда:</b> ${escapeHtml(meta.done)}</span>
      </div>
      <div class="workspace-action-guide__next">
        <small>После выполнения</small>
        <a href="${escapeHtml(meta.nextHref)}">${escapeHtml(meta.nextLabel)} <span aria-hidden="true">→</span></a>
      </div>
      <p><b>Стоп:</b> ${escapeHtml(meta.guard)}</p>
    </section>
  `;
}

function pageHeader(title, description, actions = "") {
  const activeSection = state.route.path.startsWith("/workspace/")
    ? state.route.path.replace("/workspace/", "")
    : "home";
  const meta = WORKSPACE_SECTION_META[activeSection] || WORKSPACE_SECTION_META.home;
  const inFactoryFlow = Boolean(factoryFlowStage(activeSection));
  const nativeV4 = window.CONTENTENGINE_DESKTOP_V4 === true;
  const ownsFocusedAction = ["board", "generation", "review", "placement", "stats", "tasks"].includes(activeSection);
  const guideLink = academyRoutesReachable()
    ? `<a class="workspace-guide-link" href="${escapeHtml(meta.guideHref || "#/learn")}"><span aria-hidden="true">?</span> Инструкция для этого шага</a>`
    : "";
  return `
    ${nativeV4 && !ownsFocusedAction ? workspaceActionGuideMarkup(meta) : ""}
    <section class="workspace-page-intro">
      <header class="page-header">
        <div class="page-header-copy">
          <p class="eyebrow">${escapeHtml(meta.kicker)}</p>
          <h1>${escapeHtml(title)}</h1>
          <p>${escapeHtml(description)}</p>
          <span class="page-context-note"><i aria-hidden="true"></i>${escapeHtml(meta.note)}</span>
        </div>
        <div class="page-actions">
          ${actions}
          ${guideLink}
        </div>
      </header>
      ${!nativeV4 && inFactoryFlow ? factoryFlowMarkup(activeSection) : ""}
    </section>
    ${nativeV4 ? "" : workspaceDirectionMarkup(meta)}
  `;
}

function factoryFlowMarkup(activeSection) {
  const canonicalSection = canonicalFactoryFlowSection(activeSection);
  return `
    <nav class="factory-flow" aria-label="Этапы производственного цикла">
      <ol style="--workflow-step-count:${FACTORY_FLOW.length}">
        ${FACTORY_FLOW.map((item) => `
          <li class="${item.key === canonicalSection ? "active" : ""}">
            <a href="#/workspace/${item.key}" ${item.key === canonicalSection ? 'aria-current="step"' : ""}>
              <span>${item.step}</span>
              <div><strong>${item.label}</strong><small>${item.hint}</small></div>
            </a>
          </li>
        `).join("")}
      </ol>
    </nav>
  `;
}

function sectionBody(sectionState, readyMarkup) {
  if ((sectionState.status === "loading" || sectionState.status === "idle") && !sectionState.data) {
    return `<div class="skeleton-stack" role="status"><span class="sr-only">Загружаем данные…</span><div aria-hidden="true" class="skeleton"></div><div aria-hidden="true" class="skeleton"></div><div aria-hidden="true" class="skeleton"></div></div>`;
  }
  if (sectionState.status === "error") {
    console.error(sectionState.error);
    const section = state.route.path.startsWith("/workspace/")
      ? state.route.path.replace("/workspace/", "")
      : "";
    if (section === "media") {
      return `
        <div class="empty-state media-catalog-recovery" role="alert">
          <div class="empty-icon" aria-hidden="true">!</div>
          <h3>Не удалось обновить список файлов</h3>
          <p>Вы всё равно можете выбрать и загрузить файлы выше. Повторите обновление списка позже.</p>
          <button class="btn btn-secondary btn-small" type="button" data-action="refresh-section" data-section="media">Повторить обновление</button>
        </div>`;
    }
    const retry = state.sections[section]
      ? `<button class="btn btn-secondary btn-small" type="button" data-action="refresh-section" data-section="${escapeHtml(section)}">Повторить</button>`
      : "";
    return `<div class="empty-state" role="alert"><div class="empty-icon" aria-hidden="true">!</div><h3>Не удалось загрузить раздел</h3><p>Проверьте соединение и попробуйте ещё раз. Если ошибка повторится, сообщите руководителю команды.</p>${retry}</div>`;
  }
  if (sectionState.status === "refreshing") {
    return `<div class="refresh-indicator" role="status"><span aria-hidden="true"></span>Обновляем данные…</div>${readyMarkup}`;
  }
  return readyMarkup;
}

async function loadWorkspaceBoardFallback() {
  const [mediaResult, tasksResult] = await Promise.allSettled([
    withUiTimeout(
      state.api.workspaceSection("media", { projectId: currentWorkspaceProjectId() }),
      WORKSPACE_REQUEST_TIMEOUT_MS,
      "workspace_board_media_fallback_timeout",
    ),
    withUiTimeout(
      state.api.workspaceSection("tasks", { projectId: currentWorkspaceProjectId() }),
      WORKSPACE_REQUEST_TIMEOUT_MS,
      "workspace_board_tasks_fallback_timeout",
    ),
  ]);
  if (mediaResult.status === "rejected" && tasksResult.status === "rejected") {
    throw mediaResult.reason || tasksResult.reason || new Error("workspace_board_fallback_unavailable");
  }
  const mediaData = mediaResult.status === "fulfilled"
    ? mediaResult.value?.data ?? mediaResult.value ?? {}
    : {};
  const tasksData = tasksResult.status === "fulfilled"
    ? tasksResult.value?.data ?? tasksResult.value ?? {}
    : {};
  return {
    folders: [],
    media: listFrom(mediaData, "media", "items"),
    tasks: listFrom(tasksData, "tasks", "items"),
    capabilities: {
      manage_folders: ["owner", "admin"].includes(
        String(state.bootstrap?.membership?.role || "").toLowerCase(),
      ),
      move_items: false,
    },
    _meta: {
      has_more: false,
      next_cursor: null,
      degraded: true,
    },
  };
}

function emptyState(icon, title, message, action = null) {
  const actionMarkup = action?.href
    ? `<a class="btn btn-secondary btn-small empty-state-action" href="${escapeHtml(action.href)}">${escapeHtml(action.label)} <span aria-hidden="true">→</span></a>`
    : action?.target
      ? `<button class="btn btn-secondary btn-small empty-state-action" type="button" data-action="scroll-to" data-target="${escapeHtml(action.target)}">${escapeHtml(action.label)} <span aria-hidden="true">↑</span></button>`
      : "";
  return `<div class="empty-state"><div class="empty-icon" aria-hidden="true">${icon}</div><h3>${escapeHtml(title)}</h3><p>${escapeHtml(message)}</p>${actionMarkup}</div>`;
}

function reserveManagerEmailAction(cooldowns, email) {
  const key = String(email || "").trim().toLowerCase();
  const now = Date.now();
  const blockedUntil = Number(cooldowns.get(key) || 0);
  if (blockedUntil > now) return Math.max(1, Math.ceil((blockedUntil - now) / 1_000));
  cooldowns.set(key, now + MANAGER_EMAIL_ACTION_COOLDOWN_MS);
  return 0;
}

async function handleClick(event) {
  if (state.mobileNavOpen && !event.target.closest(".mobile-nav, .mobile-nav-trigger")) {
    setMobileNavOpen(false);
  }
  const homeProject = event.target.closest("[data-ce-v4-project-id]");
  if (homeProject) {
    const projectId = String(homeProject.dataset.ceV4ProjectId || "");
    const projectName = String(homeProject.dataset.ceV4ProjectName || "Проект");
    if (projectId) {
      activateWorkspaceProject(projectId, projectName);
      state.workspaceBoard.selectedFolderId = "all";
    }
  }
  const workspaceAnchor = event.target.closest('a[href^="#/workspace/"]');
  if (workspaceAnchor) {
    const href = String(workspaceAnchor.getAttribute("href") || "");
    const scopedHref = scopedWorkspaceAnchorHref(href);
    if (scopedHref && scopedHref !== href) workspaceAnchor.setAttribute("href", scopedHref);
  }
  const workspaceDragHandle = event.target.closest("[data-workspace-drag-item]");
  if (workspaceDragHandle) {
    state.workspaceBoard.selectedItemKey = workspaceDragHandle.dataset.itemKey
      || workspaceBoardItemKey(
        workspaceDragHandle.dataset.entityType,
        workspaceDragHandle.dataset.entityId,
      );
    state.workspaceBoard.notice = "Объект выбран. Укажите папку в панели справа или перетащите ручку на папку.";
    state.workspaceBoard.error = "";
    renderWorkspace("board");
    window.queueMicrotask(() => document.querySelector("[data-workspace-item-drawer] button[data-action='move-workspace-item']")?.focus());
    return;
  }
  const control = event.target.closest("[data-action]");
  if (!control) return;
  const action = control.dataset.action;

  if (action === "reset-stats-filters") {
    event.preventDefault();
    const route = statsRouteHref({
      period: null,
      platform: null,
      content_type: null,
      q: null,
      result_page: 1,
    });
    navigate(route.replace(/^#/, ""));
    return;
  }

  if (action === "set-stats-layout") {
    event.preventDefault();
    const layout = control.dataset.layout === "cards" ? "cards" : "table";
    navigate(statsRouteHref({ layout, result_page: 1 }).replace(/^#/, ""));
    return;
  }

  if (action === "export-stats-csv") {
    event.preventDefault();
    exportVisibleStatsCsv();
    return;
  }

  if (action === "finder-mode") {
    event.preventDefault();
    const mode = control.dataset.ceV4FinderMode === "organize" ? "organize" : "browse";
    const query = new URLSearchParams(state.route.query);
    query.set("view", mode);
    query.delete("create");
    navigate(`/workspace/board?${query.toString()}`);
    return;
  }

  if (action === "finder-view") {
    event.preventDefault();
    window.ContentEngineFinderV4?.setView?.(control.dataset.ceV4FinderView, control);
    return;
  }

  if (action === "finder-quicklook") {
    event.preventDefault();
    if (!control.disabled) void window.ContentEngineFinderV4?.openSelected?.(control);
    return;
  }

  if (action === "finder-upload") {
    event.preventDefault();
    navigate("/workspace/media");
    return;
  }

  if (action === "refresh-admin-people") {
    if (!canManageTeam() || state.adminPeople.busyKey) return;
    state.adminPeople.notice = "";
    await loadAdminPeople({ silent: true });
    return;
  }

  if (action === "open-project-chooser") {
    navigate("/workspace/home", false, { scopeProject: false });
    return;
  }

  if (action === "open-project-create") {
    navigate("/workspace/home?view=new", false, { scopeProject: false });
    return;
  }

  if (action === "retry-project-flow") {
    control.disabled = true;
    state.projectFlow.status = "idle";
    state.projectFlow.error = null;
    try {
      await loadProjectFlow({ silent: true, force: true });
      if (state.route.path === "/workspace/home") render();
    } finally {
      if (control.isConnected) control.disabled = false;
    }
    return;
  }

  if (action === "select-ai-learning-category") {
    const category = aiLearningCategory(control.dataset.categoryKey);
    state.aiLearning.historicalCaseFilter = "all";
    const scopeId = currentAiLearningMarketScopeId();
    navigate(`/workspace/ai?category=${encodeURIComponent(category)}&view=${encodeURIComponent(currentAiLearningView())}${scopeId ? `&scope=${encodeURIComponent(scopeId)}` : ""}`);
    return;
  }

  if (action === "select-ai-market-learning-scope") {
    const scopeId = String(control.dataset.scopeId || "").trim().toLowerCase();
    const marketIndex = currentProjectAiLearningMarketIndex();
    const scopeExists = marketIndex
      && marketIndex.scopes.some(
        (scope) => scope.scopeId === scopeId,
      );
    if (!scopeExists) {
      toast("Привязка категории изменилась. Обновите ИИ‑центр.", "error");
      return;
    }
    navigate(`/workspace/ai?scope=${encodeURIComponent(scopeId)}&category=${encodeURIComponent(currentAiLearningCategory())}&view=${encodeURIComponent(currentAiLearningView())}`);
    return;
  }

  if (action === "select-ai-learning-view") {
    const view = aiLearningView(control.dataset.view);
    const scopeId = currentAiLearningMarketScopeId();
    navigate(`/workspace/ai?category=${encodeURIComponent(currentAiLearningCategory())}&view=${encodeURIComponent(view)}${scopeId ? `&scope=${encodeURIComponent(scopeId)}` : ""}`);
    return;
  }

  if (action === "refresh-ai-learning") {
    state.aiLearning.notice = "";
    state.aiLearning.error = "";
    await loadAiLearningControlRoom();
    return;
  }

  if (action === "select-ai-historical-case-filter") {
    state.aiLearning.historicalCaseFilter = aiHistoricalCaseFilter(
      control.dataset.historicalCaseFilter,
    );
    if (state.route.path === "/workspace/ai") renderWorkspace("ai");
    return;
  }

  if (action === "choose-ai-knowledge-file") {
    const form = control.closest("#ai-knowledge-file-form");
    const input = form?.elements?.file;
    if (!(input instanceof HTMLInputElement) || input.disabled) return;
    input.click();
    return;
  }

  if (action === "decide-ai-teaching-card") {
    await decideAiTeachingCard(control);
    return;
  }

  if (action === "decide-ai-historical-case") {
    await decideAiHistoricalCase(control);
    return;
  }

  if (action === "decide-ai-research-receipt") {
    await decideAiResearchReceipt(control);
    return;
  }

  if (action === "retry-ai-historical-case-import") {
    await importAiHistoricalCasesFromRegisteredSource({
      sourceId: control.dataset.sourceId,
      productCategory: control.dataset.productCategory,
      filename: control.dataset.filename || state.aiLearning.historicalImport.filename,
    });
    return;
  }

  if (action === "choose-media-upload-files") {
    const form = control.closest("#media-upload-form");
    const input = form?.elements?.file;
    if (
      !(input instanceof HTMLInputElement)
      || input.disabled
      || form.dataset.busy === "true"
    ) return;
    input.click();
    return;
  }

  if (action === "remove-media-upload-file") {
    const form = control.closest("#media-upload-form");
    const input = form?.elements?.file;
    const index = Number(control.dataset.fileIndex);
    if (
      !form
      || !(input instanceof HTMLInputElement)
      || !Number.isInteger(index)
      || form.dataset.busy === "true"
    ) return;
    const files = Array.from(input.files || []);
    if (index < 0 || index >= files.length) return;
    files.splice(index, 1);
    setMediaInputFiles(input, files);
    form.dataset.dirty = "true";
    showSelectedFiles(form);
    return;
  }

  if (action === "copy-tracking-link") {
    const value = String(control.dataset.trackingUrl || "");
    if (!isHttpsUrl(value)) {
      toast("Ссылка учёта недоступна. Обновите раздел публикаций.", "error");
      return;
    }
    try {
      await navigator.clipboard.writeText(value);
      toast("Ссылка для публикации скопирована.", "success");
    } catch {
      toast(value, "info");
    }
    return;
  }

  if (action === "open-publishing-schedule") {
    // Гейт боевой приёмки: очередь ни разу не доведена до published —
    // до первого зелёного прогона наряд ставит только owner/admin.
    if (!canManageTeam()) {
      toast(
        "Очередь авторазмещения ещё не прошла боевую приёмку — публикуем вручную по чек-листу задачи.",
        "info",
      );
      return;
    }
    const projectId = requireWorkspaceProjectId();
    if (!projectId) return;
    openPublishingScheduleDialog({
      projectId,
      placementId: String(control.dataset.placementId || ""),
      placementTitle: String(control.dataset.placementTitle || ""),
      placementPlatform: String(control.dataset.placementPlatform || ""),
    });
    return;
  }

  if (action === "open-video-finalization") {
    const projectId = requireWorkspaceProjectId();
    if (!projectId) return;
    openVideoFinalizationDialog({
      projectId,
      mediaId: String(control.dataset.mediaId || ""),
      generationJobId: String(control.dataset.generationJobId || ""),
    });
    return;
  }

  if (action === "open-client-review-issue") {
    openClientReviewIssueDialog({
      campaignId: String(control.dataset.campaignId || ""),
      campaignName: String(control.dataset.campaignName || ""),
    });
    return;
  }

  if (action === "open-client-review-links") {
    openClientReviewLinksDialog({
      campaignId: String(control.dataset.campaignId || ""),
      campaignName: String(control.dataset.campaignName || ""),
    });
    return;
  }

  if (action === "copy-client-review-url") {
    try {
      await navigator.clipboard.writeText(String(control.dataset.url || ""));
      toast("Ссылка скопирована. Отправьте её клиенту.", "success");
    } catch {
      toast("Скопируйте ссылку вручную — буфер обмена недоступен.", "error");
    }
    return;
  }

  if (action === "close-client-review-links") {
    control.closest("dialog")?.close();
    return;
  }

  if (action === "revoke-client-review-link") {
    control.disabled = true;
    try {
      await state.api.revokeClientReviewLink({
        link_id: String(control.dataset.linkId || ""),
      });
      toast("Ссылка отозвана: клиент больше не откроет витрину.", "success");
      control.closest("dialog")?.dispatchEvent(
        new CustomEvent("client-review-refresh"),
      );
    } catch (error) {
      control.disabled = false;
      toast(`Не удалось отозвать: ${actionErrorMessage(error)}`, "error");
    }
    return;
  }

  if (action === "toggle-client-intake") {
    control.disabled = true;
    try {
      await state.api.configureClientReviewIntake({
        link_id: String(control.dataset.linkId || ""),
        intake_enabled: control.dataset.enable === "true",
      });
      toast(
        control.dataset.enable === "true"
          ? "Клиентский ввод включён: у клиента появилась вкладка «Материалы и бриф»."
          : "Клиентский ввод выключен.",
        "success",
      );
      control.closest("dialog")?.dispatchEvent(
        new CustomEvent("client-review-refresh"),
      );
    } catch (error) {
      control.disabled = false;
      toast(`Не удалось переключить: ${actionErrorMessage(error)}`, "error");
    }
    return;
  }

  if (action === "load-client-intake") {
    const linkId = String(control.dataset.linkId || "");
    const box = control.closest("dialog")?.querySelector(
      `[data-client-intake-box="${CSS.escape(linkId)}"]`,
    );
    if (!box) return;
    control.disabled = true;
    box.innerHTML = `<p class="muted tiny">Загружаем брифы и файлы…</p>`;
    try {
      const data = await state.api.listClientIntake({ link_id: linkId });
      const uploads = data.uploads || [];
      const urls = uploads.length
        ? await state.api.signedPrivateObjectUrls(
          uploads.map((upload) => upload.object_name),
        )
        : new Map();
      const briefs = data.briefs || [];
      box.innerHTML = `
        ${briefs.length ? briefs.map((brief) => `
          <div class="callout" style="margin-top:8px">
            <strong>Бриф: ${escapeHtml(brief.brief_product)}</strong>
            <span class="badge">${escapeHtml(
              brief.status === "accepted"
                ? "принят в работу"
                : brief.status === "returned"
                  ? "возвращён"
                  : "на рассмотрении",
            )}</span>
            <p class="tiny">Аудитория: ${escapeHtml(brief.brief_audience)}</p>
            <p class="tiny">Тон: ${escapeHtml(brief.brief_tone)}</p>
            ${brief.brief_restrictions ? `<p class="tiny">Ограничения: ${escapeHtml(brief.brief_restrictions)}</p>` : ""}
            ${brief.brief_wishes ? `<p class="tiny">Пожелания: ${escapeHtml(brief.brief_wishes)}</p>` : ""}
            ${brief.status === "submitted" ? `
              <div class="inline-actions">
                <button class="btn btn-primary btn-small" type="button" data-action="decide-client-intake-brief" data-brief-id="${escapeHtml(brief.id)}" data-link-id="${escapeHtml(linkId)}" data-decision="accepted">Принять в работу</button>
                <button class="btn btn-secondary btn-small" type="button" data-action="decide-client-intake-brief" data-brief-id="${escapeHtml(brief.id)}" data-link-id="${escapeHtml(linkId)}" data-decision="returned">Вернуть с комментарием</button>
              </div>
            ` : brief.operator_comment ? `<p class="tiny muted">Комментарий команды: ${escapeHtml(brief.operator_comment)}</p>` : ""}
          </div>
        `).join("") : `<p class="muted tiny" style="margin-top:8px">Брифов пока нет.</p>`}
        ${uploads.length ? `
          <p class="eyebrow" style="margin-top:10px">Файлы клиента</p>
          ${uploads.map((upload) => `
            <p class="tiny">
              ${urls.get(upload.object_name)
                ? `<a href="${escapeHtml(urls.get(upload.object_name))}" target="_blank" rel="noopener noreferrer">${escapeHtml(upload.original_filename)}</a>`
                : escapeHtml(upload.original_filename)}
              · ${escapeHtml(String(Math.ceil(Number(upload.size_bytes || 0) / 1048576)))} МБ
              · права подтверждены клиентом
            </p>
          `).join("")}
        ` : ""}
      `;
    } catch (error) {
      box.innerHTML = `<p class="muted tiny">Не удалось загрузить: ${escapeHtml(actionErrorMessage(error))}</p>`;
    }
    control.disabled = false;
    return;
  }

  if (action === "load-client-review-append") {
    const linkId = String(control.dataset.linkId || "");
    const box = control.closest("dialog")?.querySelector(
      `[data-client-intake-box="${CSS.escape(linkId)}"]`,
    );
    if (!box) return;
    control.disabled = true;
    box.innerHTML = `<p class="muted tiny">Загружаем ролики кампании…</p>`;
    try {
      const data = await state.api.listCampaignReviewCandidates({
        campaign_id: String(control.dataset.campaignId || ""),
      });
      const candidates = data.candidates || [];
      box.innerHTML = candidates.length ? `
        <p class="eyebrow" style="margin-top:10px">Добавить в ссылку</p>
        ${candidates.map((item) => `
          <label class="option">
            <input type="checkbox" data-client-review-append-media value="${escapeHtml(item.media_object_id)}" />
            <span>${escapeHtml(item.original_filename || item.media_object_id)}
              <small class="muted"> · ${item.qa_status === "approved" ? "QA принят" : "без QA-проверки"}</small></span>
          </label>
        `).join("")}
        <label class="option">
          <input type="checkbox" data-client-review-append-attest />
          <span><strong>Беру кураторскую ответственность за ролики без QA</strong></span>
        </label>
        <button class="btn btn-primary btn-small" type="button" data-action="submit-client-review-append" data-link-id="${escapeHtml(linkId)}">Добавить выбранные</button>
        <p class="tiny muted">Уже включённые в ссылку ролики будут тихо пропущены; клиент увидит новые по той же ссылке.</p>
      ` : `<p class="muted tiny">У кампании нет готовых роликов.</p>`;
    } catch (error) {
      box.innerHTML = `<p class="muted tiny">Не удалось загрузить: ${escapeHtml(actionErrorMessage(error))}</p>`;
    }
    control.disabled = false;
    return;
  }

  if (action === "submit-client-review-append") {
    const box = control.closest("[data-client-intake-box]");
    const mediaIds = Array.from(
      box?.querySelectorAll("[data-client-review-append-media]:checked") || [],
    ).map((item) => String(item.value));
    if (!mediaIds.length) {
      toast("Отметьте хотя бы один ролик.", "error");
      return;
    }
    control.disabled = true;
    try {
      const result = await state.api.appendClientReviewLinkItems({
        link_id: String(control.dataset.linkId || ""),
        media_ids: mediaIds,
        curator_attested:
          box?.querySelector("[data-client-review-append-attest]")?.checked
            === true,
      });
      toast(
        `Добавлено роликов: ${result?.link?.added ?? 0}. Клиент увидит их по той же ссылке.`,
        "success",
      );
      control.closest("dialog")?.dispatchEvent(
        new CustomEvent("client-review-refresh"),
      );
    } catch (error) {
      control.disabled = false;
      toast(`Не удалось добавить: ${actionErrorMessage(error)}`, "error");
    }
    return;
  }

  if (action === "decide-client-intake-brief") {
    const decision = String(control.dataset.decision || "");
    let comment = "";
    if (decision === "returned") {
      comment = String(
        window.prompt("Комментарий клиенту: что доработать в брифе?") || "",
      ).trim();
      if (comment.length < 3) {
        toast("Для возврата нужен комментарий клиенту.", "error");
        return;
      }
    }
    control.disabled = true;
    try {
      await state.api.decideClientIntakeBrief({
        brief_id: String(control.dataset.briefId || ""),
        decision,
        comment,
      });
      toast(
        decision === "accepted"
          ? "Бриф принят в работу. Клиент увидит статус на своей странице."
          : "Бриф возвращён клиенту с комментарием.",
        "success",
      );
      control.closest("dialog")?.querySelector(
        `[data-action="load-client-intake"][data-link-id="${CSS.escape(String(control.dataset.linkId || ""))}"]`,
      )?.click();
    } catch (error) {
      control.disabled = false;
      toast(`Решение не записано: ${actionErrorMessage(error)}`, "error");
    }
    return;
  }

  if (action === "use-local-media-fixture") {
    const form = control.closest("#media-upload-form");
    const input = form?.elements?.file;
    if (!LOCAL_QA_MEDIA_FIXTURE_ENABLED || !(input instanceof HTMLInputElement)) return;
    control.disabled = true;
    try {
      const response = await fetch(LOCAL_QA_MEDIA_FIXTURE_URL, { cache: "no-store" });
      if (!response.ok) throw new Error("local_media_fixture_unavailable");
      const blob = await response.blob();
      const file = new File([blob], "ugc_bombbar_pro_poster.png", {
        type: "image/png",
      });
      const transfer = new DataTransfer();
      transfer.items.add(file);
      input.files = transfer.files;
      input.dispatchEvent(new Event("change", { bubbles: true }));
      form.dataset.dirty = "true";
      toast("Тестовое фото подставлено. Проверьте артикул и загрузите файл.", "info");
    } catch {
      toast("Не удалось подставить тестовое фото из локальной сборки.", "error");
    } finally {
      if (control.isConnected) control.disabled = false;
    }
    return;
  }

  if (action === "open-training-practical-media") {
    await openTrainingPracticalMedia(control);
    return;
  }

  if (action === "refresh-training-practical-reviews") {
    await refreshTrainingPracticalReviews({ control });
    return;
  }

  if (action === "training-mastery-next") {
    const courseCode = String(document.querySelector("[data-course-lesson-player]")?.dataset.courseCode || "");
    const course = learningCourses().find((item) => item.code === courseCode);
    if (!course) return;
    const snapshot = syncCourseMasteryPanel(course);
    const step = String(control.dataset.masteryStep || snapshot?.nextStep || "lessons");
    if (step === "lessons") {
      const journey = restoreLessonJourney(course);
      const understood = new Set(journey.understoodLessonIds);
      const required = new Set(courseRequiredLessonIds(course));
      const index = course.lessons.findIndex((lesson) => required.has(lesson.id) && !understood.has(lesson.id));
      if (index >= 0) syncCourseLessonJourney(course, reduceLessonJourney(journey, { type: "open", index }, course.lessons), { focus: true, scroll: true });
    } else if (step === "practice") {
      const required = new Set(course.mastery.requiredWalkthroughIds);
      const root = Array.from(document.querySelectorAll(`[data-training-course="${CSS.escape(course.code)}"]`))
        .find((item) => required.has(String(item.dataset.trainingWalkthrough || "")) && item.dataset.trainingComplete !== "true");
      scrollElementIntoView(root, "center");
      root?.querySelector('[data-action="training-walkthrough-play"]')?.focus({ preventScroll: true });
    } else if (step === "test") {
      const target = document.querySelector("#course-check");
      scrollElementIntoView(target, "start");
      target?.focus({ preventScroll: true });
    } else if (step === "confirmation") {
      const target = document.querySelector(".course-completion-card");
      scrollElementIntoView(target, "center");
      target?.querySelector("[data-course-ack]:not(:checked)")?.focus({ preventScroll: true });
    }
    track("training_mastery_step_opened", { module_code: course.code, mastery_step: step });
    return;
  }

  if (["training-lesson-open", "training-lesson-toggle", "training-lesson-understood"].includes(action)) {
    const courseCode = String(document.querySelector("[data-course-lesson-player]")?.dataset.courseCode || "");
    const lessons = Array.from(document.querySelectorAll("[data-course-lesson]"));
    const course = learningCourses().find((item) => item.code === courseCode);
    if (!course || !lessons.length) return;
    const index = Math.max(0, Math.min(lessons.length - 1, Number(control.dataset.lessonIndex) || 0));
    const current = restoreLessonJourney(course);
    if (action === "training-lesson-toggle" && current.activeIndex === index && control.getAttribute("aria-expanded") === "true") {
      const lesson = lessons[index];
      lesson.querySelector("[data-course-lesson-details]")?.setAttribute("hidden", "");
      control.setAttribute("aria-expanded", "false");
      control.setAttribute("aria-label", `Открыть урок «${lesson.querySelector("h2")?.textContent || index + 1}»`);
      return;
    }
    const wasUnderstood = current.understood.includes(index);
    const next = action === "training-lesson-understood"
        ? reduceLessonJourney(current, {
          type: wasUnderstood ? "reopen" : "understand",
          index,
          moveNext: !wasUnderstood,
        }, course.lessons)
      : reduceLessonJourney(current, { type: "open", index }, course.lessons);
    syncCourseLessonJourney(course, next, {
      focus: true,
      scroll: action !== "training-lesson-toggle",
    });
    if (action === "training-lesson-understood") {
      track(wasUnderstood ? "training_lesson_reopened" : "training_lesson_completed", {
        module_code: courseCode,
        lesson_index: index + 1,
        learning_track: restoreLearningTrack(),
      });
      if (!wasUnderstood) toast("Урок отмечен понятным. Прогресс сохранён на этом устройстве.", "success");
    }
    return;
  }

  if (action === "close-training-achievement") {
    closeTrainingAchievement();
    return;
  }

  if (action === "play-training-fanfare") {
    const played = playTrainingFanfare();
    if (played) {
      control.disabled = true;
      control.innerHTML = '<span aria-hidden="true">✓</span> Фанфары сыграли';
    } else {
      toast("В этом браузере звук недоступен, но ачивка уже сохранена.", "info");
    }
    return;
  }

  if (action === "toggle-work-notifications") {
    event.preventDefault();
    if (window.CONTENTENGINE_DESKTOP_V4 === true) {
      navigate("/workspace/work?view=notifications");
      return;
    }
    if (!state.myWork.notificationsOpen && state.mobileNavOpen) setMobileNavOpen(false);
    state.myWork.notificationsOpen = !state.myWork.notificationsOpen;
    refreshNotificationLayer({ focus: state.myWork.notificationsOpen });
    if (
      state.myWork.notificationsOpen
      && ["idle", "error"].includes(state.myWork.notificationsStatus)
    ) {
      void loadMyWorkNotifications();
    }
    return;
  }

  if (action === "open-work-notification") {
    const notificationId = String(control.dataset.notificationId || "");
    if (notificationId) void markMyWorkNotificationsRead([notificationId]);
    return;
  }

  if (action === "mark-all-notifications-read") {
    await markAllMyWorkNotificationsRead();
    return;
  }

  if (action === "refresh-my-work") {
    state.myWork.notice = "";
    state.myWork.error = "";
    window.queueMicrotask(() => loadWorkGenerations({ silent: true }));
    await loadSection("work");
    return;
  }

  if (action === "reset-my-work-filters") {
    state.myWork.filters = normalizeMyWorkFilters();
    state.myWork.selectedViewId = "";
    state.myWork.notice = "";
    state.myWork.error = "";
    await loadSection("work");
    return;
  }

  if (action === "load-more-my-work") {
    await loadMoreMyWork();
    return;
  }

  if (action === "apply-my-work-view") {
    const viewId = String(control.dataset.viewId || "");
    const view = state.myWork.savedViews.find((item) => item.id === viewId);
    state.myWork.selectedViewId = view?.id || "";
    state.myWork.filters = normalizeMyWorkFilters(view?.filters);
    state.myWork.notice = view
      ? `Фильтр «${view.name}» применён.`
      : "";
    state.myWork.error = "";
    await loadSection("work");
    return;
  }

  if (action === "delete-my-work-view") {
    const viewId = String(control.dataset.viewId || "");
    if (!viewId) return;
    state.myWork.pendingDeleteViewId = viewId;
    state.myWork.notice = "";
    state.myWork.error = "";
    renderWorkspace("work");
    window.queueMicrotask(() => {
      document.querySelector('[data-action="confirm-delete-my-work-view"]')?.focus({ preventScroll: true });
    });
    return;
  }

  if (action === "cancel-delete-my-work-view") {
    state.myWork.pendingDeleteViewId = "";
    renderWorkspace("work");
    return;
  }

  if (action === "confirm-delete-my-work-view") {
    const viewId = String(control.dataset.viewId || "");
    const version = Number(control.dataset.viewVersion || 0);
    if (!viewId || state.myWork.pendingDeleteViewId !== viewId) return;
    try {
      await state.api.savedWorkViews({
        action: "delete",
        view_id: viewId,
        expected_version: version,
      });
      if (state.myWork.selectedViewId === viewId) {
        state.myWork.selectedViewId = "";
        state.myWork.filters = normalizeMyWorkFilters();
      }
      await reloadSavedWorkViews();
      state.myWork.notice = "Сохранённый фильтр удалён.";
      state.myWork.error = "";
    } catch (error) {
      state.myWork.error = actionErrorMessage(error);
    }
    state.myWork.pendingDeleteViewId = "";
    renderWorkspace("work");
    return;
  }

  if (action === "training-walkthrough-play") {
    await toggleTrainingWalkthrough(trainingWalkthroughRoot(control));
    return;
  }

  if (action === "training-mode-select") {
    const root = trainingWalkthroughRoot(control);
    stopTrainingWalkthroughSession(root);
    const mode = setTrainingWalkthroughMode(root, control.dataset.trainingModeValue);
    persistTrainingWalkthroughState(root);
    if (mode === "practice") {
      root?.querySelector("[data-training-practice-option]")?.focus?.({ preventScroll: true });
    }
    return;
  }

  if (action === "training-walkthrough-jump") {
    setTrainingWalkthroughStepAndPersist(
      trainingWalkthroughRoot(control),
      Number(control.dataset.trainingStepTarget) || 0,
    );
    return;
  }

  if (action === "training-walkthrough-reset") {
    const root = trainingWalkthroughRoot(control);
    resetTrainingWalkthroughState(root);
    persistTrainingWalkthroughState(root, { syncServer: false });
    root?.querySelector('[data-action="training-walkthrough-play"]')?.focus({ preventScroll: true });
    toast("Повтор начат локально. Уже полученный зачёт сохраняется в рабочем профиле.", "info");
    return;
  }

  if (["training-walkthrough-previous", "training-walkthrough-next"].includes(action)) {
    const root = trainingWalkthroughRoot(control);
    const current = Math.max(0, Number(root?.dataset?.trainingStep) || 0);
    const next = action === "training-walkthrough-previous"
      ? current - 1
      : current + 1;
    setTrainingWalkthroughStepAndPersist(root, next);
    return;
  }

  if (action === "set-portal-theme") {
    applyPortalTheme(control.dataset.themeValue, { persist: true, announce: true });
    return;
  }

  if (action === "set-navigation-mode") {
    applyNavigationMode(control.dataset.navigationMode, {
      persist: true,
      announce: true,
      rerender: true,
    });
    return;
  }

  if (action === "select-workspace-folder") {
    state.workspaceBoard.selectedFolderId = String(control.dataset.folderId || "all");
    state.workspaceBoard.selectedItemKey = "";
    if (state.workspaceBoard.selectedFolderId !== "all") {
      state.workspaceBoard.provenanceFilter = "all";
    }
    state.workspaceBoard.notice = "";
    state.workspaceBoard.error = "";
    state.workspaceBoard.pendingArchiveFolderId = "";
    state.workspaceBoard.hasMore = false;
    state.workspaceBoard.nextCursor = null;
    state.workspaceBoard.visibleItemLimit = WORKSPACE_BOARD_VISIBLE_STEP;
    if (isWorkspaceSmartFolderId(state.workspaceBoard.selectedFolderId)) {
      renderWorkspace("board");
      await loadSection("board", { silent: true });
    } else {
      await loadSection("board");
    }
    return;
  }

  if (action === "select-workspace-provenance") {
    const provenanceFilter = String(control.dataset.provenanceFilter || "")
      .trim()
      .toLowerCase();
    if (!["source", "research", "generated_output"].includes(provenanceFilter)) {
      toast("Не удалось определить раздел файлов. Обновите страницу.", "error");
      return;
    }
    state.workspaceBoard.selectedFolderId = "all";
    state.workspaceBoard.selectedItemKey = "";
    state.workspaceBoard.query = "";
    state.workspaceBoard.entityType = "all";
    state.workspaceBoard.provenanceFilter = provenanceFilter;
    state.workspaceBoard.notice = "";
    state.workspaceBoard.error = "";
    state.workspaceBoard.pendingArchiveFolderId = "";
    state.workspaceBoard.hasMore = false;
    state.workspaceBoard.nextCursor = null;
    state.workspaceBoard.visibleItemLimit = WORKSPACE_BOARD_VISIBLE_STEP;
    await loadSection("board");
    return;
  }

  if (action === "open-workspace-item") {
    state.workspaceBoard.selectedItemKey = String(
      control.dataset.itemKey
      || workspaceBoardItemKey(control.dataset.entityType, control.dataset.entityId),
    );
    state.workspaceBoard.notice = "";
    state.workspaceBoard.error = "";
    renderWorkspace("board");
    window.queueMicrotask(() => document.querySelector("[data-workspace-item-drawer] [data-action='close-workspace-item']")?.focus());
    return;
  }

  if (action === "create-from-workspace-media") {
    const projectId = requireWorkspaceProjectId();
    if (!projectId) return;
    const mediaId = String(control.dataset.entityId || "").trim();
    if (!mediaId) {
      toast("Файл больше не найден. Обновите раздел «Файлы».", "error");
      return;
    }
    persistGenerationMediaSelection(mediaId, projectId);
    clearGenerationFormDraft();
    state.sections.generation.status = "idle";
    state.sections.generation.error = null;
    navigate(`/workspace/generation?view=create&project_id=${encodeURIComponent(projectId)}`);
    return;
  }

  if (action === "publish-workspace-result") {
    const projectId = requireWorkspaceProjectId();
    if (!projectId) return;
    const mediaId = String(control.dataset.entityId || "").trim();
    if (!mediaId) {
      toast("Файл больше не найден. Обновите раздел «Файлы».", "error");
      return;
    }
    await openPublishResultDialog({
      projectId,
      mediaId,
      mediaTitle: String(control.dataset.entityTitle || ""),
    });
    return;
  }

  if (action === "reject-workspace-result") {
    const projectId = requireWorkspaceProjectId();
    if (!projectId) return;
    const mediaId = String(control.dataset.entityId || "").trim();
    if (!mediaId) {
      toast("Файл больше не найден. Обновите раздел.", "error");
      return;
    }
    openRejectResultDialog({
      projectId,
      mediaId,
      mediaTitle: String(control.dataset.entityTitle || ""),
    });
    return;
  }

  if (action === "close-workspace-item") {
    state.workspaceBoard.selectedItemKey = "";
    renderWorkspace("board");
    window.queueMicrotask(() => document.querySelector(".workspace-board__item-open")?.focus());
    return;
  }

  if (action === "move-workspace-item") {
    await moveWorkspaceBoardItem({
      entityType: control.dataset.entityType,
      entityId: control.dataset.entityId,
      itemKey: control.dataset.itemKey,
      destinationFolderId: control.dataset.targetFolderId || control.dataset.folderId,
    });
    return;
  }

  if (action === "archive-workspace-folder") {
    await archiveWorkspaceBoardFolder(
      control.dataset.folderId,
      Number(control.dataset.folderVersion) || 1,
    );
    return;
  }

  if (action === "confirm-archive-workspace-folder") {
    await archiveWorkspaceBoardFolder(
      control.dataset.folderId,
      Number(control.dataset.folderVersion) || 1,
      { confirmed: true },
    );
    return;
  }

  if (action === "cancel-archive-workspace-folder") {
    state.workspaceBoard.pendingArchiveFolderId = "";
    state.workspaceBoard.notice = "Архивация отменена.";
    state.workspaceBoard.error = "";
    renderWorkspace("board");
    return;
  }

  if (action === "reset-workspace-filters") {
    state.workspaceBoard.query = "";
    state.workspaceBoard.entityType = "all";
    state.workspaceBoard.provenanceFilter = "all";
    state.workspaceBoard.notice = "";
    state.workspaceBoard.error = "";
    state.workspaceBoard.hasMore = false;
    state.workspaceBoard.nextCursor = null;
    state.workspaceBoard.visibleItemLimit = WORKSPACE_BOARD_VISIBLE_STEP;
    await loadSection("board");
    return;
  }

  if (action === "show-more-workspace-items") {
    state.workspaceBoard.visibleItemLimit = Math.min(
      WORKSPACE_BOARD_MEMORY_CAP,
      state.workspaceBoard.visibleItemLimit + WORKSPACE_BOARD_VISIBLE_STEP,
    );
    renderWorkspace("board");
    return;
  }

  if (action === "load-more-workspace-items") {
    await loadMoreWorkspaceBoard();
    return;
  }

  if (action === "refresh-research-stage-control") {
    const runId = String(state.productResearch.record?.id || "").trim();
    const branchId = String(
      state.productResearch.stageControl.data?.selectedBranch?.branchId || "",
    ).trim();
    if (!runId) {
      toast("Не удалось определить исследование. Обновите раздел.", "error");
      return;
    }
    await loadResearchStageControl({ runId, branchId });
    return;
  }

  if (action === "focus-research-trends-stage") {
    const stage = document.querySelector('[data-research-stage="trends"]');
    if (!stage) {
      toast("Этап «Тренды» пока не загружен. Обновите исследование.", "error");
      return;
    }
    stage.scrollIntoView({
      block: "center",
      behavior: prefersReducedMotion() ? "auto" : "smooth",
    });
    const correction = stage.querySelector('textarea[name="trend_correction"]');
    correction?.focus({ preventScroll: true });
    return;
  }

  if (action === "select-research-stage-branch") {
    const runId = String(state.productResearch.record?.id || "").trim();
    const branchId = String(control.dataset.branchId || "").trim().toLowerCase();
    const knownBranch = state.productResearch.stageControl.data?.branches
      ?.some((branch) => branch.branchId === branchId);
    if (!runId || !knownBranch) {
      toast("Ветка изменилась. Обновите снимок этапов.", "error");
      return;
    }
    await loadResearchStageControl({ runId, branchId });
    return;
  }

  if (action === "resume-research-stage-recompute") {
    const stageControl = state.productResearch.stageControl;
    const active = stageControl.data?.activeRecompute;
    const requestId = String(control.dataset.requestId || "").trim().toLowerCase();
    const childRunId = String(control.dataset.childRunId || "").trim().toLowerCase();
    if (
      !active
      || active.requestId !== requestId
      || active.childRunId !== childRunId
      || active.status !== "queued"
      || active.providerAttemptCount !== 0
      || active.cancelReason === "branch_changed_after_prepare"
    ) {
      toast("Сохранённый пересчёт изменился. Сначала проверьте его статус.", "error");
      await loadResearchStageControl({
        runId: state.productResearch.record?.id,
        branchId: stageControl.data?.selectedBranch?.branchId,
      });
      return;
    }
    stageControl.status = "mutating";
    stageControl.error = "";
    stageControl.notice = "Вручную проверяем сохранённый дочерний запуск. Новый recompute-запрос не создаётся.";
    renderWorkspace("research");
    try {
      await state.api.resumeResearchStageRecompute(childRunId, requestId, {
        project_id: currentWorkspaceProjectId(),
      });
      stageControl.notice = "Сохранённый запуск принят. Проверьте статус; повторный платный запрос не создавался.";
    } catch (error) {
      stageControl.error = `${actionErrorMessage(error)} Запрос ${requestId.slice(0, 8)}… сохранён; не повторяйте его автоматически.`;
    }
    await loadResearchStageControl({
      runId: state.productResearch.record?.id,
      branchId: stageControl.data?.selectedBranch?.branchId,
      silent: true,
    });
    return;
  }

  if (action === "refresh-product-research") {
    await pollProductResearchStatus();
    return;
  }

  if (action === "revalidate-product-research-response") {
    const research = state.productResearch;
    const runId = String(research.record?.id || "").trim().toLowerCase();
    const projectId = currentWorkspaceProjectId();
    if (
      !runId
      || String(research.record?.failureCode || "").trim().toLowerCase()
        !== "provider_response_invalid"
    ) {
      toast("Сохранённый ответ нельзя повторно проверить. Обновите статус исследования.", "error");
      return;
    }
    const previousRecord = research.record;
    research.requestId += 1;
    const requestId = research.requestId;
    research.phase = "processing";
    research.error = "";
    research.record = {
      ...previousRecord,
      status: "processing",
      failureCode: "",
      failureMessage: "",
      statusNotice: "Повторно проверяем тот же сохранённый ответ провайдера. Новый платный запрос не создаётся.",
    };
    renderWorkspace("research");
    try {
      const raw = await withUiTimeout(
        state.api.revalidateProductResearchResponse(runId, { projectId }),
        WORKSPACE_REQUEST_TIMEOUT_MS,
        "product_research_revalidation_timeout",
      );
      if (
        requestId !== research.requestId
        || runId !== String(research.record?.id || "").trim().toLowerCase()
        || projectId !== currentWorkspaceProjectId()
      ) return;
      research.record = {
        ...normalizeProductResearch(raw, research.record),
        statusNotice: "",
      };
      prepareRecommendedResearchHandoff(research.record);
      const kind = productResearchStatusKind(research.record.status);
      research.phase = kind === "failed"
        ? "error"
        : kind === "active"
        ? "processing"
        : kind;
      research.error = kind === "failed"
        ? (research.record.failureMessage || "Сохранённый ответ всё ещё не прошёл проверку.")
        : "";
      toast(
        kind === "completed"
          ? "Сохранённый ответ проверен без нового платного запроса."
          : "Повторная проверка сохранена. Новый платный запрос не создавался.",
        kind === "completed" ? "success" : "info",
      );
    } catch (error) {
      if (requestId !== research.requestId) return;
      const code = String(error?.serverCode || error?.code || "").trim();
      const timedOut = String(error?.message || "")
        === "product_research_revalidation_timeout";
      const message = code === "provider_response_expired"
        ? "Срок хранения ответа у провайдера истёк. Повторная проверка без нового платного запуска уже невозможна."
        : timedOut
        ? "Сервер не завершил повторную проверку вовремя. Новый платный запрос не создавался; обновите статус."
        : `${actionErrorMessage(error)} Новый платный запрос не создавался.`;
      research.phase = "error";
      research.error = message;
      research.record = { ...previousRecord, statusNotice: "" };
      toast(message, "error");
    }
    if (state.route.path === "/workspace/research") renderWorkspace("research");
    scheduleProductResearchPolling();
    return;
  }

  if (action === "copy-product-research-support-id") {
    const researchId = String(
      control.dataset.researchId || state.productResearch.record?.id || "",
    ).trim().toLowerCase();
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/u.test(researchId)) {
      toast("ID запуска недоступен. Обновите страницу и откройте исследование снова.", "error");
      return;
    }
    try {
      await navigator.clipboard.writeText(`ContentEngine research run: ${researchId}`);
      toast("ID запуска скопирован для поддержки.", "success");
    } catch {
      toast(`ID запуска: ${researchId}`, "info");
    }
    return;
  }

  if (action === "generate-research-scenario") {
    const projectId = requireWorkspaceProjectId();
    if (!projectId) return;
    if (normalizeGenerationRepairPolicy(state.generationRepair?.data)?.applied) {
      toast("Сначала завершите точное исправление после QA. Новый сценарий не должен подменять активный repair-контекст.", "error");
      return;
    }
    const previousRecord = state.productResearch.record;
    const runId = String(previousRecord?.id || "").trim().toLowerCase();
    control.disabled = true;
    try {
      const stageControl = await loadResearchStageControl({
        runId,
        branchId: state.productResearch.stageControl.data?.selectedBranch?.branchId,
        silent: true,
      });
      if (
        !runId
        || stageControl?.available !== true
        || String(stageControl.runId || "").trim().toLowerCase() !== runId
        || stageControl.guidance?.generationHandoffAllowed !== true
        || String(stageControl.guidance?.currentDraftId || "")
          .trim().toLowerCase() !== String(previousRecord?.draftId || "")
          .trim().toLowerCase()
        || String(state.productResearch.record?.id || "").trim().toLowerCase()
          !== runId
      ) {
        invalidateGenerationStateForResearch(runId);
        beginNewProductResearch({
          previousRecord,
          previousRunId: runId,
          prefill: {
            researchFocus: "Повторно собрать доказательства после изменения разбора источников",
          },
          notice: "Прежний снимок сохранён. Сервер запретил его передачу в генерацию, поэтому подготовлена новая форма; платный анализ не запущен.",
        });
        navigate("/workspace/research", true);
        toast(
          "Свежесть исследования не подтверждена. Проверьте предзаполненную форму и отдельно подтвердите новый анализ.",
          "error",
        );
        return;
      }
      const handoff = createContentGenerationHandoff(
        state.productResearch.record,
        Number(control.dataset.scenarioIndex),
        Date.now(),
        { projectId },
      );
      state.contentGenerationHandoff = handoff;
      resetGenerationSpecState();
      persistContentGenerationHandoff(handoff);
      state.sections.generation.status = "idle";
      state.sections.generation.error = null;
      state.generationSpend.status = "idle";
      await track("research_scenario_sent_to_generation", {
        research_id: handoff.researchId,
        draft_id: handoff.draftId,
        scenario_position: handoff.scenario.position,
        platform: handoff.scenario.platform,
      });
      navigate(workspaceProjectHref("/workspace/generation?view=create", projectId));
    } catch (error) {
      toast(actionErrorMessage(error), "error");
    } finally {
      if (control.isConnected) control.disabled = false;
    }
    return;
  }

  if (action === "dismiss-generation-handoff") {
    const form = control.closest("#mock-batch-form");
    if (form) persistGenerationFormDraft(form, { manual: true });
    clearContentGenerationHandoff();
    invalidateGenerationSpec(form, "Источник исследования удалён из текущего замысла.");
    if (state.route.path === "/workspace/generation") renderWorkspace("generation");
    toast("Связь со сценарием убрана. Форму можно заполнить вручную.", "info");
    return;
  }

  if (action === "restore-auto-generation-brief") {
    const form = control.closest("#mock-batch-form");
    const identity = syncGenerationProductIdentity(form);
    const compiled = syncAutomaticGenerationBrief(form, { force: true, identity });
    if (!compiled?.ready) {
      toast(compiled?.blockers?.[0]?.message || "Сначала выберите проверенное фото товара.", "error");
      return;
    }
    form.dataset.dirty = "true";
    invalidateGenerationSpec(form);
    syncContentGenerationHandoff(form);
    syncGenerationFormReadiness(form);
    persistGenerationFormDraft(form);
    try {
      await runGenerationSpecControl(
        form,
        state.generationSpec.data?.generationSpec ? "patch" : "prepare",
      );
      toast("Серверная версия ТЗ подготовлена бесплатно. Проверьте точный prompt и утвердите версию отдельной кнопкой.", "success");
    } catch (error) {
      state.generationSpec.error = actionErrorMessage(error);
      syncGenerationSpecUi(form);
      toast(actionErrorMessage(error), "error");
    }
    form.elements.brief?.focus({ preventScroll: true });
    return;
  }

  if (action === "cancel-generation-spec-review") {
    const form = control.closest("#mock-batch-form");
    if (!form) return;
    clearGenerationSpecApprovalReview(form, {
      render: true,
      clearPriceConfirmation: true,
    });
    toast("Проверка закрыта. Версия не одобрена, платный запуск не выполнялся.", "info");
    return;
  }

  if ([
    "confirm-generation-spec-approval",
    "request-generation-spec-revision",
  ].includes(action)) {
    const form = control.closest("#mock-batch-form");
    if (!form) return;
    const decision = action === "confirm-generation-spec-approval"
      ? "approve"
      : "revision";
    const outcome = evaluateGenerationSpecApprovalReview(form, decision);
    if (!outcome.ok || !outcome.rpcAction) {
      clearGenerationSpecApprovalReview(form, {
        render: true,
        clearPriceConfirmation: true,
      });
      toast(
        outcome.kind === "blocked"
          ? "Сначала прочитайте точный prompt, сверьте реплику и поставьте явное подтверждение."
          : "Версия или её prompt изменились. Откройте проверку заново для текущих version и hash.",
        "error",
      );
      return;
    }
    const approvalReview = state.generationSpec.approvalReview;
    if (outcome.rpcAction !== "approve") {
      clearGenerationSpecApprovalReview(form, {
        render: false,
        clearPriceConfirmation: true,
      });
    }
    control.disabled = true;
    try {
      const envelope = await runGenerationSpecControl(form, outcome.rpcAction, {
        approvalReview,
      });
      if (!envelope) throw new Error("Это решение для ТЗ сейчас недоступно.");
      toast(
        outcome.rpcAction === "approve"
          ? "Эта точная версия ТЗ одобрена. Платный запуск всё ещё требует отдельного подтверждения цены."
          : "Версия отправлена на доработку. Подтверждение цены очищено; платный запуск не выполнялся.",
        "success",
      );
    } catch (error) {
      state.generationSpec.error = actionErrorMessage(error);
      clearGenerationSpecApprovalReview(form, {
        render: false,
        clearPriceConfirmation: true,
      });
      syncGenerationSpecUi(form);
      syncGenerationFormReadiness(form);
      toast(actionErrorMessage(error), "error");
    } finally {
      if (control.isConnected) control.disabled = false;
    }
    return;
  }

  if ([
    "run-generation-spec-recommended-action",
    "control-generation-spec",
  ].includes(action)) {
    const form = control.closest("#mock-batch-form");
    const specAction = String(
      control.dataset.generationSpecControl || "",
    ).trim().toLowerCase();
    if (!form) return;
    if (specAction === "start_new_research") {
      const generationSpec = state.generationSpec.data?.generationSpec;
      const provenance = generationSpec?.research_provenance || {};
      const exactScope = generationSpec?.exact_scope || {};
      const researchId = String(provenance.research_id || "")
        .trim()
        .toLowerCase();
      const currentResearch = state.productResearch.record;
      const currentResearchId = String(currentResearch?.id || "")
        .trim()
        .toLowerCase();
      if (
        currentResearchId
        && currentResearchId !== researchId
        && productResearchStatusKind(currentResearch?.status) === "active"
      ) {
        navigate("/workspace/research", true);
        toast(
          "Сейчас выполняется другое платное исследование. Сначала дождитесь его терминального статуса; текущий запуск не был скрыт и новый не создавался.",
          "error",
        );
        return;
      }
      const matchingRecord = String(
        state.productResearch.record?.id || "",
      ).trim().toLowerCase() === researchId
        ? state.productResearch.record
        : null;
      const matchingHandoff = String(
        state.contentGenerationHandoff?.researchId || "",
      ).trim().toLowerCase() === researchId
        ? state.contentGenerationHandoff
        : null;
      const contextRecord = matchingRecord || {
        id: researchId,
        draftId: String(provenance.creative_brief_draft_id || "").trim(),
        productName: String(
          matchingHandoff?.productName
            || form.elements.product_name?.value
            || "",
        ).trim(),
        sku: String(
          matchingHandoff?.sku || form.elements.sku?.value || "",
        ).trim(),
        categoryAnalysis: {
          categoryName: String(
            exactScope.product_category
              || form.elements.product_category?.value
              || "",
          ).trim(),
        },
        researchInput: {
          sourceMediaIds: Array.isArray(exactScope.media_ids)
            ? exactScope.media_ids
            : [],
          platforms: PRODUCT_RESEARCH_PLATFORM_SET.has(exactScope.platform)
            ? [exactScope.platform]
            : [],
        },
      };
      const prefill = productResearchPrefillFromSnapshot(contextRecord, {
        sourceMediaIds: Array.isArray(exactScope.media_ids)
          ? exactScope.media_ids
          : [],
        platform: exactScope.platform,
        previousResearchId: researchId,
        researchFocus: "Повторно собрать доказательства после изменения разбора источников",
      });
      invalidateGenerationStateForResearch(researchId);
      beginNewProductResearch({
        previousRecord: contextRecord,
        preservedRecord: matchingRecord,
        previousRunId: researchId,
        prefill,
        notice: "Прежний снимок исследования сохранён. Подготовлена новая форма с исходными данными; платный анализ и генерация не запускались.",
      });
      navigate("/workspace/research", true);
      toast(
        "Разбор источника изменён. Проверьте предзаполненную форму и отдельно подтвердите запуск нового исследования.",
        "info",
      );
      return;
    }
    if (specAction === "confirm_spend") {
      form.elements.real_spend_confirmation?.focus({ preventScroll: true });
      toast("Версия ТЗ утверждена. Если хотите запуск, отдельно проверьте цену и поставьте подтверждение оплаты.", "info");
      return;
    }
    if (specAction === "review") {
      if (!openGenerationSpecApprovalReview(form)) {
        toast("Текущая версия изменилась. Обновите или сохраните ТЗ и откройте проверку заново.", "error");
      }
      return;
    }
    if (
      specAction === "approve"
      && state.generationSpec.data?.recommendedNextAction?.action === "approve"
      && state.generationSpec.data.recommendedNextAction.requiresConfirmation === true
    ) {
      if (!openGenerationSpecApprovalReview(form)) {
        toast("Для одобрения откройте точную серверную версию и проверьте её заново.", "error");
      }
      return;
    }
    control.disabled = true;
    try {
      if (specAction === "refresh") {
        await refreshGenerationSpec(form, { force: true });
        toast("Статус управляемого ТЗ обновлён без вызова провайдера и списания.", "success");
      } else {
        if (["prepare", "patch"].includes(specAction)) {
          const identity = syncGenerationProductIdentity(form);
          const compiled = syncAutomaticGenerationBrief(form, {
            force: true,
            identity,
          });
          if (!compiled?.ready) {
            const failure = generationSpecPreparationFailure(form, compiled);
            throw new CreatorApiError(failure.message, { code: failure.code });
          }
        }
        const requestedTargetVersion = Number(
          control.dataset.targetSpecVersion,
        );
        const envelope = await runGenerationSpecControl(form, specAction, {
          targetSpecVersion: Number.isInteger(requestedTargetVersion)
            && requestedTargetVersion > 0
            ? requestedTargetVersion
            : null,
        });
        if (!envelope) throw new Error("Это действие с ТЗ сейчас недоступно.");
        toast(
          specAction === "approve"
            ? "Эта серверная версия утверждена. Платный запуск всё ещё требует отдельного подтверждения цены."
            : "История управляемого ТЗ обновлена бесплатно; платный провайдер не запускался.",
          "success",
        );
      }
    } catch (error) {
      state.generationSpec.error = actionErrorMessage(error);
      syncGenerationSpecUi(form);
      syncGenerationFormReadiness(form);
      toast(actionErrorMessage(error), "error");
    } finally {
      if (control.isConnected) control.disabled = false;
    }
    return;
  }

  if (action === "prepare-generation-acceptance") {
    prepareGenerationAcceptance(control.dataset.generationModel);
    return;
  }

  if (action === "refresh-generation-model-acceptance") {
    control.disabled = true;
    try {
      await loadGenerationModelAcceptance({ force: true });
      toast(
        state.generationModelAcceptance.status === "ready"
          ? "Статус реальных файлов и QA обновлён без нового запуска."
          : "Серверный статус пока не подтверждён. Новый платный запуск не создан.",
        state.generationModelAcceptance.status === "ready"
          ? "success"
          : "info",
      );
    } finally {
      if (control.isConnected) control.disabled = false;
    }
    return;
  }

  if (action === "check-runway-readiness") {
    await checkRunwayReadiness(control);
    return;
  }

  if (action === "retry-generation-learning") {
    const form = control.closest("#mock-batch-form");
    const identity = selectedGenerationProductIdentity(form);
    if (!form || !identity || !generationLearningKey(form, identity)) {
      toast("Сначала выберите проверенный исходник товара.", "error");
      return;
    }
    control.disabled = true;
    try {
      await loadGenerationLearningPolicy(form, identity, { force: true });
      if (state.generationLearning.status === "ready") {
        toast("Обученное ТЗ проверено. Платный запуск снова доступен.", "success");
      } else {
        toast("Проверка обученного ТЗ пока недоступна. Платный запуск не создан.", "error");
      }
    } finally {
      if (control.isConnected) control.disabled = false;
    }
    return;
  }

  if (action === "disable-generation-learning" || action === "enable-generation-learning") {
    const form = control.closest("#mock-batch-form");
    const identity = selectedGenerationProductIdentity(form);
    const key = generationLearningKey(form, identity);
    if (!form || !identity || !key) {
      toast("Сначала выберите проверенный исходник товара.", "error");
      return;
    }
    state.generationLearning.enabledKey =
      action === "enable-generation-learning" ? key : "";
    invalidateGenerationSpec(form);
    const compiled = syncAutomaticGenerationBrief(form, {
      force: true,
      identity,
    });
    syncContentGenerationHandoff(form);
    syncGenerationLearningStatus(form);
    syncGenerationFormReadiness(form);
    if (!compiled?.ready) {
      toast("Не удалось восстановить безопасное ТЗ.", "error");
      return;
    }
    form.dataset.dirty = "true";
    persistGenerationFormDraft(form);
    toast(
      action === "disable-generation-learning"
        ? "Совет ИИ отключён. Ваш замысел и выбранные параметры сохранены."
        : "Совет ИИ применён по вашему выбору. Тема, способ съёмки и длительность не изменены.",
      "success",
    );
    return;
  }

  if (action === "restore-project-placement") {
    const projectId = requireWorkspaceProjectId();
    const reviewId = String(control.dataset.reviewId || "").trim().toLowerCase();
    if (!projectId || !contentReviewUuid(reviewId)) {
      toast("Не удалось определить проверку и проект. Обновите страницу.", "error");
      return;
    }
    control.disabled = true;
    try {
      const raw = await state.api.restoreProjectPlacement(reviewId, { projectId });
      const result = raw?.data ?? raw ?? {};
      const placementId = String(
        result.placement_id || result.placement?.id || "",
      ).trim().toLowerCase();
      if (!contentReviewUuid(placementId)) throw new Error("project_placement_restore_invalid");
      state.sections.placement.status = "idle";
      state.sections.stats.status = "idle";
      state.projectFlow.status = "idle";
      const freshFlow = await loadProjectFlow({ silent: true, force: true });
      const nextRoute = exactProjectNextActionRoute(freshFlow, projectId)
        || workspaceProjectHref(
          `/workspace/placement?view=next&placement=${encodeURIComponent(placementId)}`,
          projectId,
        );
      await flowHandoff(
        nextRoute,
        "Публикация восстановлена",
        "Открываем точный материал",
      );
    } catch (error) {
      toast(actionErrorMessage(error), "error");
    } finally {
      if (control.isConnected) control.disabled = false;
    }
    return;
  }

  if (action === "prepare-generation-repair") {
    const reviewId = String(control.dataset.reviewId || "").trim().toLowerCase();
    if (!contentReviewUuid(reviewId)) {
      toast("Не удалось определить исходное QA-решение. Обновите страницу.", "error");
      return;
    }
    control.disabled = true;
    try {
      const repairPolicy = await loadGenerationRepairForReview(reviewId);
      if (!repairPolicy?.applied) {
        toast(
          "Для этого решения нет безопасного структурного исправления. Нужен новый материал или отдельное решение руководителя.",
          "info",
        );
        return;
      }
      navigate(workspaceProjectHref(
        `/workspace/generation?view=create&review=${encodeURIComponent(reviewId)}`,
        requireWorkspaceProjectId(),
      ));
      toast(
        "Исправление восстановлено. Проверьте авто-ТЗ и отдельно подтвердите цену одного запуска.",
        "success",
      );
    } catch (error) {
      state.generationRepair.status = "error";
      state.generationRepair.error = error;
      toast(actionErrorMessage(error), "error");
    } finally {
      if (control.isConnected) control.disabled = false;
    }
    return;
  }

  if (action === "open-generated-content-review") {
    const projectId = requireWorkspaceProjectId();
    if (!projectId) return;
    const mediaId = String(control.dataset.mediaId || "").trim().toLowerCase();
    if (!isWorkspaceProjectId(mediaId)) {
      toast("У готового материала не найден точный файл. Обновите задачи и генерацию.", "error");
      return;
    }
    state.contentReview.pendingMediaId = mediaId;
    state.contentReview.record = null;
    state.contentReview.phase = "idle";
    state.contentReview.error = "";
    state.contentReview.notice = "Выберите контекст публикации и запустите обязательную проверку готового фото или видео.";
    const reviewRoute = workspaceProjectHref(
      `/workspace/review?view=new&media=${encodeURIComponent(mediaId)}`,
      projectId,
    );
    navigate(reviewRoute);
    return;
  }

  if (action === "start-generated-video-review") {
    const mediaId = String(control.dataset.mediaId || "").trim().toLowerCase();
    await startGeneratedVideoReviewFromEvidence(mediaId);
    return;
  }

  if (action === "open-content-review") {
    const reviewId = String(control.dataset.reviewId || "");
    const catalog = normalizeContentReviewCatalog(state.sections.review.data || {});
    const selected = catalog.runs.find((item) => item.id === reviewId);
    if (!selected) {
      toast("Эта проверка не найдена в загруженной истории. Обновите раздел.", "error");
      return;
    }
    state.contentReview.record = selected;
    state.contentReview.phase = "refreshing";
    state.contentReview.error = "";
    state.contentReview.notice = "";
    renderWorkspace("review");
    await pollContentReviewStatus({ silent: true, refreshMedia: true });
    scheduleContentReviewPolling(250);
    window.queueMicrotask(() => document.querySelector("[data-review-result-id], .content-review-progress, .content-review-failed")?.scrollIntoView({ block: "start", behavior: "smooth" }));
    return;
  }

  if (action === "download-content-review-media") {
    const reviewId = String(control.dataset.reviewId || state.contentReview.record?.id || "").trim();
    if (!contentReviewUuid(reviewId)) {
      toast("Не удалось определить проверку. Обновите страницу и попробуйте снова.", "error");
      return;
    }
    control.disabled = true;
    try {
      const response = await state.api.contentReviewStatus(reviewId, {
        projectId: currentWorkspaceProjectId(),
      });
      const hydrated = await hydratePrivateMedia(response, { refreshSignedUrls: true });
      const run = normalizeContentReviewRun(hydrated, state.contentReview.record);
      if (!run.media?.isVideo || !run.media.url || run.mediaIsStale) {
        throw new Error("Точная защищённая версия MP4 сейчас недоступна.");
      }
      state.contentReview.record = run;
      await downloadGenerationOutput(run.media.url, `review-${reviewId}`, false);
      toast("MP4 скачан.", "success");
    } catch (error) {
      toast(actionErrorMessage(error), "error");
    } finally {
      if (control.isConnected) control.disabled = false;
    }
    return;
  }

  if (action === "refresh-content-review") {
    const reviewId = String(control.dataset.reviewId || state.contentReview.record?.id || "");
    if (reviewId && reviewId !== String(state.contentReview.record?.id || "")) {
      const catalog = normalizeContentReviewCatalog(state.sections.review.data || {});
      state.contentReview.record = catalog.runs.find((item) => item.id === reviewId) || state.contentReview.record;
    }
    await pollContentReviewStatus({ refreshMedia: true });
    return;
  }

  if (action === "restore-previous-product-research") {
    const researchId = String(control.dataset.researchId || "")
      .trim()
      .toLowerCase();
    if (!restorePreservedProductResearchSnapshot(researchId)) {
      toast("Сохранённый снимок не найден в этой сессии. Обновите статус исследования по его ссылке.", "error");
      return;
    }
    navigate("/workspace/research", true);
    toast("Прежний снимок открыт без нового платного запуска.", "info");
    return;
  }

  if (action === "new-product-research") {
    if (productResearchStatusKind(state.productResearch.record?.status) === "active") {
      toast("Текущий платный анализ ещё не получил терминальный статус. Сначала обновите его, чтобы не создать второй запуск.", "error");
      await pollProductResearchStatus({ silent: false });
      return;
    }
    const previousRecord = state.productResearch.record;
    const stageControl = state.productResearch.stageControl.data;
    const sourceFreshnessBlocked = stageControl?.available === true
      && String(stageControl.runId || "").trim().toLowerCase()
        === String(previousRecord?.id || "").trim().toLowerCase()
      && stageControl.guidance?.generationHandoffAllowed !== true;
    clearProductResearchRunId();
    beginNewProductResearch({
      previousRecord,
      prefill: sourceFreshnessBlocked
        ? {
          researchFocus: "Повторно собрать доказательства после изменения разбора источников",
        }
        : {},
      notice: previousRecord?.id
        ? "Прежний снимок сохранён. Проверьте предзаполненные исходные данные; новый платный анализ не запущен."
        : "Подготовлена новая форма. Платный анализ не запущен.",
    });
    navigate("/workspace/research", true);
    window.queueMicrotask(() => document.querySelector('#product-research-start-form input[name="product_name"]')?.focus());
    return;
  }

  if (action === "archive-generation-batch") {
    const batchId = String(control.dataset.batchId || "").trim().toLowerCase();
    const projectId = requireWorkspaceProjectId();
    if (!projectId || !contentReviewUuid(batchId)) {
      toast("Не удалось определить запуск и проект.", "error");
      return;
    }
    if (control.dataset.confirmed !== "true") {
      control.dataset.confirmed = "true";
      control.dataset.originalLabel = control.textContent || "Убрать из истории";
      control.textContent = control.dataset.confirmLabel || "Подтвердить удаление";
      control.classList.add("btn-danger");
      window.setTimeout(() => {
        if (!control.isConnected || control.dataset.confirmed !== "true") return;
        control.dataset.confirmed = "false";
        control.textContent = control.dataset.originalLabel || "Убрать из истории";
        control.classList.remove("btn-danger");
      }, 6_000);
      return;
    }
    control.disabled = true;
    try {
      await state.api.archiveGenerationBatch(batchId, {
        project_id: projectId,
        confirmation: true,
      });
      const generation = state.sections.generation;
      if (Array.isArray(generation.data?.batches)) {
        generation.data = {
          ...generation.data,
          batches: generation.data.batches.filter(
            (item) => String(item?.id || "").toLowerCase() !== batchId,
          ),
        };
      }
      toast("Запуск убран из истории. Исходники и готовые файлы сохранены.", "success");
      renderWorkspace("generation");
    } catch (error) {
      toast(actionErrorMessage(error), "error");
      if (control.isConnected) {
        control.disabled = false;
        control.dataset.confirmed = "false";
        control.textContent = control.dataset.originalLabel || "Убрать из истории";
        control.classList.remove("btn-danger");
      }
    }
    return;
  }

  if (action === "reset-generation-filters") {
    document.querySelector("#generation-archive-filter-form")?.removeAttribute("data-dirty");
    state.generationArchive.filters = normalizeGenerationFilters({
      period: "4w",
      status: "all",
      query: "",
      visible: GENERATION_VISIBLE_STEP,
    });
    state.generationArchive.error = "";
    await reloadGenerationArchive();
    return;
  }

  if (action === "show-more-generation") {
    state.generationArchive.filters = normalizeGenerationFilters({
      ...state.generationArchive.filters,
      visible: Number(state.generationArchive.filters?.visible || GENERATION_VISIBLE_STEP) + GENERATION_VISIBLE_STEP,
    });
    renderWorkspace("generation");
    return;
  }

  if (action === "load-more-generation") {
    await loadMoreGenerationArchive();
    return;
  }

  if (action === "reload-page") {
    window.location.reload();
    return;
  }

  if (action === "toggle-mobile-nav") {
    setMobileNavOpen(!state.mobileNavOpen, state.mobileNavOpen);
    return;
  }

  if (action === "retry-auth-link") {
    retryAuthLinkIfIdle();
    return;
  }

  if (action === "request-new-auth-link") {
    const purpose = String(control.dataset.purpose || "recovery");
    state.authLinkError = null;
    navigate(purpose === "invite" ? "/login" : "/reset-password", true);
    return;
  }

  if (action === "prepare-failed-invites") {
    const rows = Array.isArray(state.teamInviteResult?.results) ? state.teamInviteResult.results : [];
    const emails = rows
      .filter((item) => !["invited", "already_exists"].includes(item.status))
      .map((item) => String(item.email || "").trim())
      .filter(Boolean);
    const field = document.querySelector("#team-invite-form textarea[name='emails']");
    if (field && emails.length) {
      field.value = [...new Set(emails)].join("\n");
      field.closest("form").dataset.dirty = "true";
      scrollElementIntoView(field.closest(".card"));
      field.focus({ preventScroll: true });
      toast("В форму перенесены только адреса без подтверждённого результата. Проверьте список перед повтором.", "info");
    }
    return;
  }

  if (action === "refresh-manager-dashboard") {
    if (
      ["loading", "refreshing"].includes(state.managerDashboard.status)
      || ["loading", "refreshing"].includes(state.operationalHealth.status)
      || ["loading", "refreshing"].includes(state.generationSpend.status)
    ) {
      toast("Сводка уже обновляется.", "info");
      return;
    }
    await loadManagerDashboard();
    return;
  }

  if (action === "refresh-generation-spend") {
    if (["loading", "refreshing"].includes(state.generationSpend.status)) {
      toast("Денежный остаток уже проверяется.", "info");
      return;
    }
    state.generationSpend.notice = "";
    state.generationSpend.error = null;
    await loadGenerationSpendOverview();
    return;
  }

  if (action === "open-manager-access") {
    await openManagerAccessCenter(String(control.dataset.email || ""));
    return;
  }

  if (action === "reset-manager-access") {
    resetManagerAccessCenter();
    return;
  }

  if (action === "retry-manager-invite") {
    await retryManagerInvite(String(control.dataset.email || ""), control);
    return;
  }

  if (action === "send-manager-recovery") {
    const email = String(control.dataset.email || "").trim();
    if (!canManageTeam() || !hasWorkspaceAccess()) {
      toast("Отправить восстановление может только сертифицированный руководитель.", "error");
      return;
    }
    if (!email) {
      toast("У участника не указан рабочий email.", "error");
      return;
    }
    const cooldownSeconds = reserveManagerEmailAction(state.managerRecoveryCooldowns, email);
    if (cooldownSeconds > 0) {
      toast(`Повтор для этого адреса временно закрыт. Подождите ${cooldownSeconds} сек. и сначала проверьте самое свежее письмо.`, "info");
      return;
    }
    await openManagerAccessCenter(email);
    return;
  }

  if (action === "copy-manager-reminder") {
    const email = String(control.dataset.email || "участник");
    const stage = String(control.dataset.stage || "обучение");
    const message = `${email}, откройте портал Контент ИИ Завода и завершите ${stage}. Если вход не открывается или страница зависла, пришлите руководителю точный текст ошибки и снимок экрана — новый аккаунт создавать не нужно.`;
    try {
      await navigator.clipboard.writeText(message);
      toast("Напоминание скопировано.", "success");
    } catch {
      toast(message, "info");
    }
    return;
  }

  if (action === "skip-to-content") {
    const main = document.querySelector("#main-content");
    main?.focus({ preventScroll: true });
    scrollElementIntoView(main);
    return;
  }

  if (action === "logout") {
    control.disabled = true;
    await state.supabase?.auth.signOut({ scope: "local" });
    clearAuthenticatedState();
    navigate("/login", true);
    return;
  }

  if (action === "request-workspace-access") {
    if (state.workspaceAccessRequest.status === "loading") return;
    state.workspaceAccessRequest.status = "loading";
    state.workspaceAccessRequest.error = "";
    renderWorkspaceAccessRequired();
    try {
      const response = await state.api.requestWorkspaceAccess();
      state.workspaceAccessRequest.result = response;
      state.workspaceAccessRequest.status = "ready";
      persistWorkspaceAccessRequest(response);
      await track("workspace_access_requested", {
        request_id: String((response?.data ?? response)?.request?.id || ""),
      });
    } catch (error) {
      state.workspaceAccessRequest.status = "error";
      state.workspaceAccessRequest.error = actionErrorMessage(error);
    }
    renderWorkspaceAccessRequired();
    return;
  }

  if (action === "retry-bootstrap") {
    control.disabled = true;
    await loadBootstrap();
    if (hasWorkspaceAccess()) {
      try {
        if (await openFirstAvailableWorkspaceProject()) return;
      } catch (error) {
        state.workspaceAccessRequest.error = actionErrorMessage(error);
      }
    }
    establishDefaultRoute();
    render();
    return;
  }

  if (action === "scroll-to") {
    const targetId = String(control.dataset.target || "");
    let target = targetId ? document.getElementById(targetId) : null;
    if (target?.matches?.("[data-course-lesson]")) {
      const courseCode = String(document.querySelector("[data-course-lesson-player]")?.dataset.courseCode || "");
      const lessons = Array.from(document.querySelectorAll("[data-course-lesson]"));
      const course = learningCourses().find((item) => item.code === courseCode);
      const lessonIndex = lessons.indexOf(target);
      if (course && lessonIndex >= 0) {
        syncCourseLessonJourney(
          course,
          reduceLessonJourney(restoreLessonJourney(course), { type: "open", index: lessonIndex }, course.lessons),
          { focus: false, scroll: false },
        );
        target = lessons[lessonIndex];
      }
    }
    if (target) {
      scrollElementIntoView(target);
      if (target.matches?.("[data-course-lesson]")) {
        target.querySelector('[data-action="training-lesson-toggle"]')?.focus({ preventScroll: true });
      } else if (target.hasAttribute("tabindex")) target.focus({ preventScroll: true });
    }
    return;
  }

  const firstShiftEventType = FIRST_SHIFT_FULL_EVENT_TYPES[action];
  if (firstShiftEventType) {
    const practice = ensureFirstShiftState();
    const eventPayload = {
      type: firstShiftEventType,
      stepId: String(control.dataset.stepId || ""),
    };
    if (firstShiftEventType === "select") {
      eventPayload.value = String(control.value || "");
      eventPayload.selected = control.checked === true;
    }
    state.firstShift = {
      userId: practice.userId,
      ...reduceFirstShiftFullState(practice, eventPayload),
    };
    persistFirstShiftState();

    if (firstShiftEventType === "select") {
      renderFirstShift();
      window.queueMicrotask(() => {
        const selectedControl = [...app.querySelectorAll(`[data-action="${FIRST_SHIFT_FULL_ACTIONS.select}"]`)]
          .find((input) => input.dataset.stepId === eventPayload.stepId && input.value === eventPayload.value);
        selectedControl?.focus?.({ preventScroll: true });
      });
      return;
    }

    renderFirstShift();
    window.queueMicrotask(() => {
      const target = firstShiftEventType === "check"
        ? app.querySelector(".first-shift-full__feedback")
        : (["next", "previous"].includes(firstShiftEventType) && !state.firstShift.completed
            ? app.querySelector("#first-shift-step-title")
            : app.querySelector("#first-shift-full-title"));
      target?.focus?.({ preventScroll: true });
      if (["check", "next", "previous"].includes(firstShiftEventType)) scrollElementIntoView(target, "center");
    });
    if (firstShiftEventType === "restart") toast("Полная учебная смена начата заново.", "info");
    return;
  }


  if (action === "complete-course") {
    const moduleCode = control.dataset.moduleCode;
    if (state.trainingProgress.completionInFlight.has(moduleCode)) return;
    const course = learningCourses().find((item) => item.code === moduleCode);
    const mastery = course ? syncCourseMasteryPanel(course) : null;
    if (!mastery?.ready) {
      const messages = {
        lessons: "Сначала отметьте понятными уроки вашего маршрута.",
        practice: "Сначала завершите обязательную учебную лабораторию.",
        test: "Сначала пройдите рабочую аттестацию этого блока.",
        confirmation: "Подтвердите все пункты финальной самопроверки.",
      };
      toast(messages[mastery?.nextStep] || "Завершите все четыре шага освоения навыка.", "error");
      document.querySelector(`[data-course-mastery-task="${CSS.escape(mastery?.nextStep || "lessons")}"] [data-action="training-mastery-next"]`)?.click();
      return;
    }
    if (state.courseCheckResults[moduleCode]?.passed !== true) {
      toast("Сначала пройдите рабочую аттестацию этого блока.", "error");
      scrollElementIntoView(document.querySelector("#course-check-form"));
      return;
    }
    const confirmations = Array.from(document.querySelectorAll("[data-course-ack]"));
    if (!confirmations.length || confirmations.some((checkbox) => !checkbox.checked)) {
      toast("Подтвердите все пункты самопроверки.", "error");
      return;
    }
    state.trainingProgress.completionInFlight.add(moduleCode);
    syncCourseMasteryPanel(course);
    try {
      await flushRequiredTrainingProgress(course);
      await state.api.completeModule(moduleCode);
      await track("course_completed", { module_code: moduleCode });
      await loadBootstrap();
      const serverCompleted = state.bootstrap.training.completedModules.includes(moduleCode);
      if (!serverCompleted) throw new Error("Сервер не подтвердил завершение блока. Обновите страницу и проверьте результат.");
      const completed = new Set(state.bootstrap.training.completedModules);
      const nextCourse = learningCourses().find((item) => !completed.has(item.code));
      const destination = nextCourse
        ? `/learn/${encodeURIComponent(nextCourse.code)}`
        : "/learn/practical";
      await flowHandoff(
        destination,
        "Блок завершён",
        nextCourse ? "Открываем следующий учебный блок" : "Открываем пробную работу",
      );
    } catch (error) {
      toast(actionErrorMessage(error), "error");
    } finally {
      state.trainingProgress.completionInFlight.delete(moduleCode);
      if (control.isConnected) syncCourseMasteryPanel(course);
    }
    return;
  }

  if (["grant-project-member", "revoke-project-member"].includes(action)) {
    if (state.projectAccess.busyProfileId) {
      toast("Изменение доступа уже сохраняется.", "info");
      return;
    }
    await changeProjectMemberAccess(
      control,
      action === "grant-project-member" ? "grant" : "revoke",
    );
    return;
  }

  if (action === "refresh-project-members") {
    if (["loading", "refreshing"].includes(state.projectAccess.status)) return;
    await loadProjectMembers({ force: true });
    return;
  }

  if (action === "refresh-team-accounts") {
    await loadTeamAccounts({ silent: false });
    return;
  }

  if (action === "refresh-results-funnel") {
    await loadResultsFunnel({ silent: false });
    return;
  }

  if (action === "refresh-work-generations") {
    await loadWorkGenerations({ silent: false });
    return;
  }

  if (action === "media-prep") {
    await enqueueMediaPreparation(control);
    return;
  }

  if (action === "hypothesis-bind-source") {
    await bindContentHypothesisSource(control);
    return;
  }

  if (action === "hypothesis-create") {
    await createContentHypothesisFromForm();
    return;
  }

  if (action === "hypothesis-approve") {
    await approveContentHypothesisVersionAction(control);
    return;
  }

  if (action === "hypothesis-decide") {
    await decideContentHypothesisAction(control);
    return;
  }

  if (action === "video-intake-register") {
    await registerVideoIntakeLink();
    return;
  }

  if (action === "video-intake-upload") {
    focusVideoIntakeUpload();
    return;
  }

  if (action === "refresh-section") {
    const section = control.dataset.section;
    if (state.sections[section]) {
      if (section === "team" && state.projectAccess.busyProfileId) {
        toast("Сначала дождитесь подтверждения изменения доступа.", "info");
        return;
      }
      if (section === "stats") {
        // Обновление «Результатов» пересчитывает и голову воронки.
        window.queueMicrotask(() => loadResultsFunnel({ silent: true }));
      }
      if (section === "generation") {
        state.generationArchive.requestId += 1;
        state.generationArchive.loading = false;
        state.generationArchive.loadingMore = false;
        state.generationArchive.exhausted = false;
        state.generationArchive.error = "";
        state.generationArchive.nextCursor = null;
        state.generationArchive.serverLoaded = false;
        state.generationModelAcceptance.requestId += 1;
        state.generationModelAcceptance.status = "idle";
        state.generationModelAcceptance.error = null;
      }
      if (section === "team") resetProjectAccessState();
      state.sections[section].requestId += 1;
      state.sections[section].status = "idle";
      render();
    }
    return;
  }

  if (action === "refresh-home") {
    state.home.requestId += 1;
    state.home.status = "idle";
    await loadProjectFlow({ silent: true, force: true });
    if (state.route.path === "/workspace/home") render();
    return;
  }

  if (action === "probe-generation-strategy-media") {
    const form = control.closest("#mock-batch-form");
    if (form instanceof HTMLFormElement) {
      const ids = String(
        control.dataset.mediaIds
          || control.dataset.mediaId
          || control.dataset.sourceMediaId
          || "",
      ).split(",").map((item) => item.trim()).filter(Boolean);
      if (ids.length > 1) {
        await probeGenerationStrategyMediaBatch(form, ids, control);
      } else {
        await probeSelectedGenerationStrategyMedia(
          form,
          ids[0],
          control,
        );
      }
    }
    return;
  }

  if (
    action === "prepare-generation-strategy-queue-free"
    || action === "start-generation-strategy-sequentially"
  ) {
    const form = control.closest("#mock-batch-form");
    const submit = form?.querySelector("#generation-submit");
    if (
      form instanceof HTMLFormElement
      && submit instanceof HTMLButtonElement
      && !submit.disabled
      && form.dataset.busy !== "true"
    ) {
      form.requestSubmit(submit);
    }
    return;
  }

  if (action === "review-generation-strategy-exact-ten") {
    const form = control.closest("#mock-batch-form");
    const target = form?.querySelector(
      "[data-generation-strategy-spec-review], #real-generation-confirmation",
    );
    if (target instanceof HTMLElement) {
      scrollElementIntoView(target, "center");
      target.querySelector("summary, input:not(:disabled), button:not(:disabled)")
        ?.focus({ preventScroll: true });
    }
    return;
  }

  if (action === "retry-generation-strategy-start") {
    const form = control.closest("#mock-batch-form");
    const sourceMediaId = String(control.dataset.sourceMediaId || "")
      .trim().toLowerCase();
    if (form instanceof HTMLFormElement && contentReviewUuid(sourceMediaId)) {
      await retryGenerationStrategyReservedStart(form, sourceMediaId);
    }
    return;
  }

  if (action === "repeat-real-generation") {
    restoreRealGenerationDraft(control.dataset.jobId);
    return;
  }

  if (action === "repeat-generation-settings") {
    repeatGenerationSettingsFromArchive(control.dataset.batchId);
    return;
  }

  if (action === "repeat-generation-strategy") {
    await repeatGenerationStrategyFromArchive(control.dataset.jobId, control);
    return;
  }

  if (action === "load-generation-video-reference") {
    await loadGenerationVideoReferenceLineage(control.dataset.jobId);
    return;
  }

  if (action === "retry-generated-video-qa") {
    const jobId = String(control.dataset.jobId || "").trim();
    const mediaId = String(control.dataset.mediaId || "").trim().toLowerCase();
    if (!jobId || !contentReviewUuid(mediaId)) {
      toast("Не удалось сверить готовый MP4 с запуском. Обновите раздел генерации.", "error");
      return;
    }
    scheduleGeneratedVideoTechnicalQa({
      id: jobId,
      status: "succeeded",
      model: "video",
      output_media_id: mediaId,
    }, trustedCachedGenerationUrl(jobId), { force: true });
    return;
  }

  if (action === "refresh-generation-strategy-status") {
    await refreshGenerationStrategyArchiveStatus(control.dataset.jobId, control);
    return;
  }

  if (action === "check-generation-strategy") {
    const jobId = String(control.dataset.jobId || "").trim().toLowerCase();
    const outputAction = String(control.dataset.outputAction || "status");
    control.disabled = true;
    const originalLabel = control.textContent;
    control.textContent = outputAction === "download" ? "Готовим файл…" : "Проверяем…";
    try {
      // Только бесплатный strategy_status: легаси 'status' отвечает 503 на
      // recipe-задачи и никогда не вызывается из карточки стратегии.
      const result = await requestGenerationStrategyArchiveStatus(jobId);
      const status = String(result?.job?.status || "processing").toLowerCase();
      if (
        ["succeeded", "completed"].includes(status)
        && ["preview", "download"].includes(outputAction)
      ) {
        // strategy_status по контракту не возвращает подписанные ссылки
        // (signed_urls_returned: false): MP4 читается напрямую из
        // защищённого хранилища по object key каталога проверки.
        const objectName = await resolveGenerationStrategyOutputObjectName(
          result?.output?.media_id,
        );
        if (outputAction === "download") {
          const blob = await withUiTimeout(
            state.api.downloadPrivateObject(objectName),
            90_000,
            "generation_strategy_output_download_timeout",
          );
          deliverGenerationOutputBlob(blob, jobId, false);
          toast("Ролик готов. Браузеру передан свежий MP4-файл из защищённого хранилища.", "success");
        } else {
          const signedUrls = await state.api.signedPrivateObjectUrls([objectName]);
          const signedUrl = String(signedUrls.get(objectName) || "");
          if (!signedUrl || !isTrustedGenerationDownload(signedUrl)) {
            throw new Error("Защищённая ссылка на готовый ролик временно не создана. Повторите чуть позже.");
          }
          const cached = state.realGenerationResults.get(jobId);
          if (cached) {
            state.realGenerationResults.set(jobId, {
              ...cached,
              signedUrl,
              signedUrlIssuedAt: Date.now(),
            });
          }
          toast("Ролик готов — предпросмотр открыт в карточке запуска.", "success");
          if (state.route.path === "/workspace/generation") {
            renderGenerationBackgroundUpdate();
          }
        }
      } else if (result?.reconciliation?.required === true) {
        toast("Нужна ручная сверка Runway. Форма сверки открыта в этой карточке запуска.", "info");
      } else if (status === "failed") {
        toast(generationFailureMessage(result?.error?.code), "error");
      } else {
        toast(`Текущий статус генерации: ${humanGenerationStatus(status)}.`, "info");
      }
    } catch (error) {
      toast(actionErrorMessage(error), "error");
    } finally {
      if (control.isConnected) {
        control.disabled = false;
        control.textContent = originalLabel;
      }
    }
    return;
  }

  if (action === "check-real-generation") {
    const jobId = String(control.dataset.jobId || "");
    const outputAction = String(control.dataset.outputAction || "status");
    control.disabled = true;
    const originalLabel = control.textContent;
    control.textContent = outputAction === "download" ? "Готовим файл…" : "Проверяем…";
    try {
      const outcome = await waitForRealGenerationStatus(jobId, REAL_GENERATION_SOFT_TIMEOUT_MS, "manual");
      if (outcome.timedOut) {
        toast("Проверка занимает больше обычного. Она продолжается без нового платного запуска — нажмите «Проверить сейчас» немного позже.", "info");
        return;
      }
      const result = outcome.result;
      const status = String(result?.job?.status || "processing").toLowerCase();
      const photo = String(result?.job?.model || "") === "seedream5_lite";
      const contentLabel = photo ? "Фото" : "Ролик";
      const signedUrl = String(result?.signed_url || "");
      if (["succeeded", "completed"].includes(status) && signedUrl) {
        if (!isTrustedGenerationDownload(signedUrl)) throw new Error("Сервис вернул небезопасную ссылку на результат.");
        if (outputAction === "download") {
          await downloadGenerationOutput(signedUrl, jobId, photo);
          toast(`${contentLabel} готов${photo ? "о" : ""}. Браузеру передан свежий ${photo ? "PNG" : "MP4"}-файл.`, "success");
        } else {
          toast(`${contentLabel} готов${photo ? "о" : ""} — результат можно посмотреть и скачать в карточке запуска.`, "success");
        }
      } else if (status === "failed") {
        toast(generationFailureMessage(result?.job?.failure_code), "error");
      } else {
        toast(`Текущий статус генерации: ${humanGenerationStatus(status)}.`, "info");
      }
    } catch (error) {
      toast(actionErrorMessage(error), "error");
    } finally {
      if (control.isConnected) {
        control.disabled = false;
        control.textContent = originalLabel;
      }
      scheduleRealGenerationPolling();
    }
    return;
  }

  if (action === "transition-task") {
    control.disabled = true;
    try {
      const taskId = control.dataset.taskId;
      const status = control.dataset.status;
      await state.api.transitionTask(taskId, status, {}, {
        projectId: currentWorkspaceProjectId(),
      });
      await track("task_status_changed", { task_id: String(taskId), status });
      state.sections.tasks.status = "idle";
      state.projectFlow.status = "idle";
      if (["submitted", "done"].includes(status)) {
        const projectId = currentWorkspaceProjectId();
        const freshFlow = await loadProjectFlow({ silent: true, force: true });
        const nextRoute = exactProjectNextActionRoute(freshFlow, projectId)
          || workspaceProjectHref("/workspace/home", projectId);
        await flowHandoff(
          nextRoute,
          status === "done" ? "Задача завершена" : "Задача отправлена на проверку",
          "Открываем следующее действие проекта",
        );
      } else {
        toast(status === "blocked" ? "Блокер зафиксирован." : "Статус задачи обновлён.", "success");
        render();
      }
    } catch (error) {
      control.disabled = false;
      toast(actionErrorMessage(error), "error");
    }
    return;
  }

  if (action === "decide-payout") {
    if (!["owner", "admin"].includes(state.bootstrap?.membership?.role)) {
      toast("Решение по выплате доступно только руководителю.", "error");
      return;
    }
    control.disabled = true;
    try {
      const payoutId = control.dataset.payoutId;
      await state.api.decidePayout(payoutId, "approve", {
        projectId: requireWorkspaceProjectId(),
      });
      await track("payout_decided", { payout_id: String(payoutId), decision: "approve" });
      state.sections.payouts.status = "idle";
      toast("Начисление одобрено. Теперь можно отдельно зафиксировать внешнюю оплату.", "success");
      render();
    } catch (error) {
      control.disabled = false;
      toast(actionErrorMessage(error), "error");
    }
  }
}

